/* Nour — contenu FRANÇAIS (langue de référence).
   Sources : 'q:S:V' = verset (texte arabe et traductions récupérés depuis des traductions reconnues),
             'h:nom'  = hadith (voir HADITHS_REFS), 'f:nom' = repère ci-dessous.
   Règle : chaque question doit se comprendre seule. Contenu à faire relire par une personne compétente. */
'use strict';
CONTENU.fr={
lecons:{
/* ===================== RAMADAN & JEÛNE ===================== */
'r-bienvenue':{titre:"Le mois de Ramadan",
 texte:["Le Ramadan est le 9ᵉ mois du calendrier musulman, appelé calendrier hégirien. Ce calendrier est lunaire : chaque mois commence avec l'apparition du nouveau croissant de lune.",
  "L'année lunaire compte environ 354 jours. Le Ramadan avance donc d'une dizaine de jours chaque année dans notre calendrier.",
  "C'est durant ce mois que la révélation du Coran a commencé. Le jeûne du Ramadan a été rendu obligatoire la 2ᵉ année de l'Hégire."],
 retenir:"Le Ramadan est le 9ᵉ mois lunaire, le mois du Coran et du jeûne.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"Dans le calendrier musulman (hégirien), quel est le rang du mois de Ramadan ?",c:["Le 9ᵉ mois","Le 1ᵉʳ mois","Le 12ᵉ mois","Le 7ᵉ mois"],b:0,e:"Le Ramadan est le 9ᵉ mois. Le 1ᵉʳ mois de l'année hégirienne est Muharram.",s:['f:mois']},
  {q:"Sur quel astre repose le calendrier musulman (hégirien) ?",c:["La lune","Le soleil","Les étoiles","Aucun astre"],b:0,e:"Chaque mois commence avec l'apparition du nouveau croissant de lune.",s:['q:2:189','h:croissant']},
  {q:"Pourquoi la date du Ramadan avance-t-elle d'environ 11 jours chaque année ?",c:["Parce que l'année lunaire est plus courte que l'année solaire","Parce que les savants la décalent chaque année","Parce que l'année hégirienne compte 13 mois","Parce qu'on suit le calendrier solaire persan"],b:0,e:"L'année lunaire compte environ 354 jours, soit environ 11 jours de moins que l'année solaire.",s:['q:9:36']},
  {q:"Quel événement majeur a commencé pendant le mois de Ramadan ?",c:["La révélation du Coran","La construction de la Kaaba","L'Hégire vers Médine","La bataille de Uhud"],b:0,e:"Le Coran a commencé à être révélé pendant le Ramadan.",s:['q:2:185']},
  {q:"Combien de mois compte l'année musulmane (hégirienne) ?",c:["12","10","13","11"],b:0,e:"L'année hégirienne compte 12 mois lunaires.",s:['q:9:36']},
  {q:"Selon le hadith, à quel signe commence-t-on le jeûne du Ramadan ?",c:["Quand on voit le nouveau croissant de lune","Quand on voit la pleine lune","Le 15 Shaʿbân, chaque année","Après le premier vendredi qui suit Shaʿbân"],b:0,e:"« Jeûnez lorsque vous le voyez » : il s'agit du croissant de lune.",s:['h:croissant']},
  {q:"Comment s'appelle le mois qui suit le Ramadan, dont le 1ᵉʳ jour est l'Aïd al-Fitr ?",c:["Shawwâl","Shaʿbân","Rajab","Muharram"],b:0,e:"Le 1ᵉʳ Shawwâl est le jour de l'Aïd al-Fitr.",s:['f:mois']},
  {q:"Quel mois du calendrier musulman précède directement le Ramadan ?",c:["Shaʿbân","Shawwâl","Dhû l-Hijja","Safar"],b:0,e:"Shaʿbân est le 8ᵉ mois, juste avant le Ramadan.",s:['f:mois']},
  {q:"En quelle année de l'Hégire le jeûne du Ramadan est-il devenu obligatoire ?",c:["L'an 2","L'an 1","L'an 10","L'an 8"],b:0,e:"Le jeûne du Ramadan a été prescrit à Médine, en l'an 2 de l'Hégire.",s:['f:jeune2']},
  {q:"Combien de jours peut durer le mois de Ramadan ?",c:["29 ou 30 jours","Toujours 30 jours","28 jours","31 jours"],b:0,e:"Un mois lunaire dure 29 ou 30 jours, selon l'apparition du croissant suivant.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Qui doit jeûner ?",
 texte:["Le jeûne du Ramadan est obligatoire pour le musulman pubère, sain d'esprit et capable de jeûner.",
  "Le malade et le voyageur peuvent ne pas jeûner, puis rattraper les jours plus tard. La femme en période de règles ne jeûne pas et rattrape ensuite.",
  "La personne qui ne pourra jamais jeûner, comme une personne très âgée, nourrit un pauvre pour chaque jour manqué : c'est la fidya."],
 retenir:"Des facilités existent : Allah veut pour nous la facilité.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Pendant le Ramadan, que doit faire le voyageur qui n'a pas jeûné certains jours ?",c:["Rattraper ces jours plus tard","Rien du tout","Payer une amende","Jeûner deux fois plus"],b:0,e:"Il rattrape le même nombre de jours après le Ramadan.",s:['q:2:184']},
  {q:"Comment s'appelle la compensation qui consiste à nourrir un pauvre pour chaque jour de jeûne manqué ?",c:["La fidya","La sadaqa","La zakat al-fitr","La kaffâra"],b:0,e:"La fidya concerne surtout ceux qui ne pourront jamais rattraper, comme les personnes très âgées.",s:['q:2:184']},
  {q:"Le jeûne du Ramadan est-il obligatoire pour un enfant qui n'a pas atteint la puberté ?",c:["Non, mais on peut l'y habituer","Oui, dès l'âge de 7 ans","Oui, mais seulement le vendredi","Seulement pendant les dix derniers jours"],b:0,e:"Ce n'est pas obligatoire. Les Compagnons habituaient pourtant leurs enfants au jeûne, par exemple le jour de ʿÂshûrâ'.",s:['h:enfants']},
  {q:"Pendant le Ramadan, que fait la femme qui a ses règles ?",c:["Elle ne jeûne pas et rattrape les jours ensuite","Elle jeûne quand même","Elle ne rattrape jamais","Elle jeûne la moitié de la journée"],b:0,e:"Elle ne jeûne pas, puis rattrape les jours manqués après le Ramadan.",s:['h:regles']},
  {q:"Le malade qui ne jeûne pas pendant le Ramadan doit-il rattraper les jours manqués ?",c:["Oui, quand il le peut","Non, jamais","Oui, mais le double","Non, il paie toujours une amende"],b:0,e:"Il rattrape un nombre égal de jours quand il en est capable.",s:['q:2:184']},
  {q:"La femme qui a ses règles doit-elle rattraper les prières qu'elle n'a pas faites pendant cette période ?",c:["Non, elle rattrape seulement le jeûne","Oui, toutes les prières","Oui, la moitié des prières","Seulement la prière du vendredi"],b:0,e:"Elle rattrape le jeûne, mais pas la prière.",s:['h:regles']},
  {q:"D'après le verset sur le jeûne, que veut Allah pour les croyants ?",c:["La facilité","La difficulté","La fatigue","La richesse"],b:0,e:"« Allah veut pour vous la facilité, Il ne veut pas la difficulté pour vous. »",s:['q:2:185']},
  {q:"Une personne très âgée qui ne pourra plus jamais jeûner : que fait-elle ?",c:["Elle nourrit un pauvre pour chaque jour","Elle jeûne quand même","Elle n'a rien à faire","Elle rattrape après le Ramadan suivant"],b:0,e:"C'est la fidya : un repas pour un pauvre par jour non jeûné.",s:['q:2:184']},
  {q:"Pour qui le jeûne du Ramadan est-il obligatoire ?",c:["Le musulman pubère, sain d'esprit et capable de jeûner","Tous les enfants","Seulement les hommes","Seulement ceux qui ont fait le hajj"],b:0,e:"Ce sont les conditions retenues par les savants.",s:['f:conditions']},
  {q:"D'après le Coran, le jeûne a-t-il été prescrit avant les musulmans ?",c:["Oui, à ceux qui les ont précédés","Non, jamais","Seulement aux gens de La Mecque","Seulement au peuple de Nûh"],b:0,e:"« On vous a prescrit le jeûne comme on l'a prescrit à ceux d'avant vous. »",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Ce qui rompt le jeûne",
 texte:["Le jeûne commence à l'aube, au moment de la prière du Fajr, et se termine au coucher du soleil, au moment de la prière du Maghrib.",
  "Manger, boire ou avoir des rapports intimes volontairement pendant la journée rompt le jeûne.",
  "Celui qui mange ou boit par oubli continue son jeûne : il reste valable."],
 retenir:"Manger ou boire par oubli n'annule pas le jeûne.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"À quel moment de la journée commence le jeûne du Ramadan ?",c:["À l'aube (Fajr)","À minuit","Au lever du soleil","À midi"],b:0,e:"Le jeûne commence à l'aube, quand le fil blanc se distingue du fil noir.",s:['q:2:187']},
  {q:"À quel moment rompt-on le jeûne du Ramadan ?",c:["Au coucher du soleil (Maghrib)","À la nuit noire (ʿIshâ')","À 16 h","Au milieu de la nuit"],b:0,e:"On rompt le jeûne dès que le soleil est couché.",s:['h:coucher']},
  {q:"Un jeûneur boit de l'eau en ayant oublié qu'il jeûnait. Que devient son jeûne ?",c:["Il reste valable","Il est annulé","Il doit le doubler","Cela dépend de la quantité"],b:0,e:"Il complète son jeûne : c'est Allah qui l'a nourri et abreuvé.",s:['h:oubli']},
  {q:"Que se passe-t-il si un jeûneur mange volontairement en pleine journée de Ramadan ?",c:["Son jeûne est rompu","Rien ne change","C'est permis s'il est à la mosquée","C'est permis après la prière du Dhohr"],b:0,e:"Manger volontairement pendant la journée rompt le jeûne.",s:['q:2:187']},
  {q:"Selon le Coran, jusqu'à quand peut-on manger et boire pendant les nuits du Ramadan ?",c:["Jusqu'à ce que le fil blanc de l'aube se distingue du fil noir de la nuit","Jusqu'à minuit","Jusqu'au lever du soleil","Jusqu'à la prière de ʿIshâ'"],b:0,e:"C'est l'image du verset 187 de la sourate Al-Baqara.",s:['q:2:187']},
  {q:"Dans le verset sur le jeûne, que représente « le fil blanc » ?",c:["La lumière de l'aube","Un vrai fil de laine","Le croissant de lune","La première étoile du soir"],b:0,e:"Le fil blanc est la clarté de l'aube, le fil noir l'obscurité de la nuit.",s:['q:2:187']},
  {q:"Pendant le Ramadan, est-il permis de manger et boire la nuit, après le coucher du soleil ?",c:["Oui, jusqu'à l'aube","Non, jamais pendant tout le mois","Seulement de l'eau","Seulement après la prière des tarâwîh"],b:0,e:"Le jeûne ne concerne que la journée, de l'aube au coucher du soleil.",s:['q:2:187']},
  {q:"Selon le hadith, qui a « nourri et abreuvé » celui qui mange ou boit par oubli pendant le jeûne ?",c:["Allah","Sa famille","Un ange","Personne"],b:0,e:"Son jeûne reste valable : c'est Allah qui l'a nourri et abreuvé.",s:['h:oubli']},
  {q:"Pendant les journées du Ramadan, les rapports intimes entre époux sont-ils permis ?",c:["Non, ils rompent le jeûne","Oui, à tout moment","Oui, l'après-midi","Seulement le jour de ʿÂshûrâ'"],b:0,e:"Le verset 187 les permet pendant les nuits du Ramadan ; pendant la journée, ils rompent le jeûne.",s:['q:2:187']},
  {q:"Quelle prière marque la fin de la journée de jeûne ?",c:["La prière du Maghrib","La prière du Fajr","La prière du Dhohr","La prière de ʿIshâ'"],b:0,e:"Le Maghrib est la prière du coucher du soleil, l'heure de la rupture du jeûne.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"Le suhur et l'iftar",
 texte:["Le suhur est le repas pris avant l'aube. Le Prophète ﷺ a encouragé à le prendre, car il contient une bénédiction.",
  "L'iftar est la rupture du jeûne au coucher du soleil. Il est recommandé de ne pas la retarder.",
  "La sunna est de rompre le jeûne avec des dattes fraîches, sinon des dattes sèches, sinon quelques gorgées d'eau."],
 retenir:"Suhur avant l'aube. Iftar dès le coucher du soleil, avec des dattes.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"Comment s'appelle le repas pris avant l'aube pendant le Ramadan ?",c:["Le suhur","L'iftar","La walîma","L'ʿaqîqa"],b:0,e:"Le suhur est le repas de fin de nuit, avant le Fajr.",s:['h:suhur']},
  {q:"D'après le hadith, que contient le repas du suhur ?",c:["Une bénédiction","Une obligation","Rien de particulier","Une épreuve"],b:0,e:"« Prenez le suhur, car il y a dans le suhur une bénédiction. »",s:['h:suhur']},
  {q:"Avec quoi le Prophète ﷺ rompait-il son jeûne de préférence ?",c:["Des dattes","Du lait de chamelle","De la ḥarîra","Du pain"],b:0,e:"Des dattes fraîches, sinon des dattes sèches, sinon quelques gorgées d'eau.",s:['h:dattes']},
  {q:"Faut-il retarder la rupture du jeûne (l'iftar) après le coucher du soleil ?",c:["Non, il est recommandé de se hâter","Oui, d'une heure","Oui, jusqu'à ʿIshâ'","Cela n'a aucune importance"],b:0,e:"Il est recommandé de rompre le jeûne dès le coucher du soleil.",s:['h:hater']},
  {q:"Comment s'appelle le repas qui rompt le jeûne au coucher du soleil ?",c:["L'iftar","Le suhur","Le ghusl","Le dhikr"],b:0,e:"L'iftar est la rupture du jeûne.",s:['h:hater']},
  {q:"Quand il n'y avait pas de dattes, avec quoi le Prophète ﷺ rompait-il son jeûne ?",c:["Quelques gorgées d'eau","Du miel","Du lait de chèvre","Des figues"],b:0,e:"Des dattes fraîches, sinon sèches, sinon quelques gorgées d'eau.",s:['h:dattes']},
  {q:"Le Prophète ﷺ rompait-il son jeûne avant ou après la prière du Maghrib ?",c:["Avant de prier","Après avoir prié","Le lendemain","Après la prière de ʿIshâ'"],b:0,e:"Il rompait son jeûne avant de prier, avec quelques dattes.",s:['h:dattes']},
  {q:"Selon le hadith, tant que les gens se hâtent de rompre le jeûne, ils restent…",c:["Dans le bien","Dans le doute","En danger","Sans récompense"],b:0,e:"« Les gens ne cesseront d'être dans le bien tant qu'ils se hâteront de rompre le jeûne. »",s:['h:hater']},
  {q:"Le suhur est-il obligatoire pour que le jeûne soit valable ?",c:["Non, mais il est fortement recommandé","Oui, sinon le jeûne est annulé","Oui, seulement le premier jour","Il est interdit"],b:0,e:"C'est une sunna : le Prophète ﷺ l'a encouragé pour sa bénédiction.",s:['h:suhur']},
  {q:"Quel type de dattes le Prophète ﷺ préférait-il pour rompre le jeûne ?",c:["Des dattes fraîches (ruṭab)","Des dattes sèches (tamr)","Des figues sèches","Des raisins secs"],b:0,e:"Il commençait par des dattes fraîches ; à défaut, des dattes sèches.",s:['h:dattes']}
 ]},
'r-merites':{titre:"Les mérites du jeûne",
 texte:["Allah a prescrit le jeûne pour que le croyant atteigne la piété (taqwâ) : la conscience d'Allah dans chaque acte.",
  "Le Prophète ﷺ a promis le pardon des péchés passés à celui qui jeûne le Ramadan avec foi et en espérant la récompense d'Allah.",
  "À la fin du mois, chaque musulman verse la zakat al-fitr avant la prière de l'Aïd. Elle purifie le jeûneur et nourrit les pauvres."],
 retenir:"Le jeûne mène à la piété. La zakat al-fitr se verse avant la prière de l'Aïd.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"D'après le Coran, dans quel but Allah a-t-il prescrit le jeûne ?",c:["Pour atteindre la piété (taqwâ)","Pour purifier le corps uniquement","Pour commémorer l'Hégire","Pour remplacer la zakat"],b:0,e:"Le verset qui prescrit le jeûne se termine par l'espoir d'atteindre la piété.",s:['q:2:183']},
  {q:"Selon le hadith, que gagne celui qui jeûne le Ramadan avec foi et en espérant la récompense d'Allah ?",c:["Ses péchés passés sont pardonnés","Il n'a plus besoin de prier","Il est dispensé de zakat","Rien de particulier"],b:0,e:"Ses péchés passés lui sont pardonnés.",s:['h:pardon']},
  {q:"À quel moment faut-il verser la zakat al-fitr ?",c:["Avant la prière de l'Aïd al-Fitr","Un mois après le Ramadan","Au début du Ramadan uniquement","N'importe quand dans l'année"],b:0,e:"Le Prophète ﷺ a ordonné de la verser avant que les gens ne sortent pour la prière de l'Aïd.",s:['h:fitr']},
  {q:"Que signifie le mot « taqwâ » ?",c:["La piété, la conscience d'Allah","La patience (ṣabr)","La reconnaissance (shukr)","Le repentir (tawba)"],b:0,e:"La taqwâ est la crainte révérencielle d'Allah qui pousse au bien.",s:['q:2:183']},
  {q:"Qui doit verser la zakat al-fitr ?",c:["Chaque musulman, petit ou grand, homme ou femme","Seulement les riches","Seulement les hommes","Seulement ceux qui ont jeûné tout le mois"],b:0,e:"Le hadith la prescrit à chaque musulman ; le chef de famille la verse pour les siens.",s:['h:fitr']},
  {q:"Quelle quantité de nourriture le hadith fixe-t-il pour la zakat al-fitr ?",c:["Un sâʿ","Un mithqâl d'or","Un mudd de blé","Un dirham d'argent"],b:0,e:"Un sâʿ est une mesure d'environ quatre fois le creux des deux mains.",s:['h:fitr']},
  {q:"Quels aliments sont cités dans le hadith de la zakat al-fitr rapporté par Ibn ʿUmar ?",c:["Des dattes ou de l'orge","Du riz ou du couscous","De la viande ou du poisson","Du lait ou du miel"],b:0,e:"Un sâʿ de dattes ou un sâʿ d'orge.",s:['h:fitr']},
  {q:"Selon le hadith, à quelles conditions le jeûne du Ramadan efface-t-il les péchés passés ?",c:["Avec la foi et l'espoir de la récompense d'Allah","En jeûnant en silence","En jeûnant 40 jours","Sans aucune condition"],b:0,e:"Il faut jeûner avec foi et en espérant la récompense d'Allah.",s:['h:pardon']},
  {q:"Quel est le but de la zakat al-fitr, selon le hadith d'Ibn ʿAbbâs ?",c:["Purifier le jeûneur et nourrir les pauvres","Financer la construction des mosquées","Remplacer le jeûne des malades","Récompenser l'imam des tarâwîh"],b:0,e:"Elle purifie le jeûneur de ses paroles futiles et nourrit les pauvres.",s:['h:fitr_but']},
  {q:"Par quel appel commence le verset qui prescrit le jeûne du Ramadan ?",c:["« Ô les croyants ! »","« Ô les gens ! »","« Ô Prophète ! »","« Ô fils d'Adam ! »"],b:0,e:"Le verset 183 de la sourate Al-Baqara commence par « Ô les croyants ! ».",s:['q:2:183']}
 ]},
'r-nuits':{titre:"Les nuits du Ramadan",
 texte:["Les nuits du Ramadan sont l'occasion de prier davantage. Leur prière de nuit s'appelle les tarâwîh. Le Prophète ﷺ a promis le pardon à celui qui prie les nuits du Ramadan avec foi et espoir de la récompense.",
  "Pendant les dix dernières nuits, il redoublait d'efforts : il veillait la nuit en prière et réveillait sa famille.",
  "Il faisait aussi l'iʿtikâf : une retraite spirituelle à la mosquée pendant les dix derniers jours, et cela jusqu'à la fin de sa vie."],
 retenir:"Tarâwîh, dix dernières nuits, iʿtikâf : les nuits du Ramadan se vivent en prière.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"Comment appelle-t-on la prière de nuit pratiquée pendant le Ramadan ?",c:["Les tarâwîh","La prière de Duhâ","La prière d'istikhâra","La prière funéraire"],b:0,e:"Les tarâwîh sont la prière des nuits du Ramadan.",s:['h:qiyam']},
  {q:"Selon le hadith, que gagne celui qui prie les nuits du Ramadan avec foi et espoir de la récompense ?",c:["Ses péchés passés sont pardonnés","Une place au premier rang de la mosquée","Il n'a plus à jeûner","Rien de particulier"],b:0,e:"Ses péchés passés lui sont pardonnés.",s:['h:qiyam']},
  {q:"Qu'est-ce que l'iʿtikâf ?",c:["Une retraite spirituelle à la mosquée","Un voyage à La Mecque","Le jeûne de ʿÂshûrâ'","Une aumône"],b:0,e:"On reste à la mosquée pour se consacrer à l'adoration.",s:['h:itikaf']},
  {q:"Pendant quelle période du Ramadan le Prophète ﷺ faisait-il l'iʿtikâf ?",c:["Les dix derniers jours","Les dix premiers jours","Le premier jour seulement","Après l'Aïd"],b:0,e:"Il le faisait pendant les dix derniers jours du Ramadan.",s:['h:itikaf']},
  {q:"Que faisait le Prophète ﷺ pendant les dix dernières nuits du Ramadan ?",c:["Il veillait en prière et réveillait sa famille","Il voyageait","Il dormait plus tôt","Il arrêtait de jeûner"],b:0,e:"Il redoublait d'efforts dans l'adoration.",s:['h:dixnuits']},
  {q:"Le Prophète ﷺ a-t-il fait l'iʿtikâf jusqu'à la fin de sa vie ?",c:["Oui, jusqu'à sa mort","Non, une seule fois","Non, jamais","Seulement à La Mecque"],b:0,e:"ʿÂ'icha rapporte qu'il l'a pratiqué jusqu'à ce qu'Allah le rappelle à Lui.",s:['h:itikaf']},
  {q:"Où se fait l'iʿtikâf ?",c:["À la mosquée","À la maison","Dans la grotte de Hira","Au cimetière"],b:0,e:"Le Coran mentionne ceux qui sont en retraite dans les mosquées.",s:['q:2:187']},
  {q:"Quelle nuit très importante se trouve parmi les dix dernières nuits du Ramadan ?",c:["Laylat al-Qadr, la Nuit du Destin","La nuit de l'Hégire","La nuit de l'Aïd al-Adhâ","La nuit du Mawlid"],b:0,e:"Il faut la chercher dans les nuits impaires des dix dernières nuits.",s:['h:qadr']},
  {q:"La prière des tarâwîh est-elle obligatoire ?",c:["Non, c'est une prière surérogatoire très recommandée","Oui, comme les cinq prières","Oui, mais seulement à la mosquée","Elle est interdite"],b:0,e:"Le Prophète ﷺ l'a priée en groupe quelques nuits, puis a cessé de peur qu'elle ne devienne obligatoire.",s:['h:tarawih']},
  {q:"Pourquoi le Prophète ﷺ a-t-il cessé de diriger les tarâwîh en groupe après quelques nuits ?",c:["De peur qu'elles ne deviennent obligatoires","Parce qu'il était malade","Parce que la mosquée était trop petite","Parce que le Ramadan était fini"],b:0,e:"Il craignait qu'elles ne soient rendues obligatoires pour sa communauté.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, la Nuit du Destin",
 texte:["Laylat al-Qadr, la Nuit du Destin, est la nuit où la révélation du Coran a commencé.",
  "Allah dit qu'elle est « meilleure que mille mois ». Les anges y descendent, et elle est paix jusqu'à l'aube. Une sourate entière lui est consacrée : la sourate Al-Qadr (97).",
  "On la recherche dans les dix dernières nuits du Ramadan, surtout les nuits impaires, en multipliant les prières et les invocations."],
 retenir:"Meilleure que mille mois. À chercher dans les nuits impaires des dix dernières nuits.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Selon le Coran, la Nuit du Destin (Laylat al-Qadr) est meilleure que combien de temps ?",c:["Mille mois","Cent jours","Une année","Dix nuits"],b:0,e:"Elle est meilleure que mille mois, soit plus de 83 ans.",s:['q:97:3']},
  {q:"Quelle sourate du Coran est consacrée à la Nuit du Destin (Laylat al-Qadr) ?",c:["Al-Qadr","Al-Fâtiha","Al-Ikhlâs","Yâ-Sîn"],b:0,e:"La sourate 97, Al-Qadr, porte le nom de cette nuit.",s:['q:97:1']},
  {q:"Pendant quelles nuits du Ramadan faut-il chercher en priorité la Nuit du Destin (Laylat al-Qadr) ?",c:["Les nuits impaires des dix dernières nuits","Les dix premières nuits","La première nuit","La nuit de l'Aïd"],b:0,e:"Les nuits impaires des dix dernières : 21, 23, 25, 27 et 29.",s:['h:qadr']},
  {q:"Quel événement a eu lieu pendant la Nuit du Destin (Laylat al-Qadr) ?",c:["Le début de la révélation du Coran","L'Hégire vers Médine","La naissance du Prophète ﷺ","Le premier pèlerinage"],b:0,e:"La révélation du Coran a commencé pendant cette nuit.",s:['q:97:1']},
  {q:"Selon la sourate Al-Qadr, qui descend pendant la Nuit du Destin ?",c:["Les anges et l'Esprit (Jibrîl)","Les prophètes","Les djinns","Personne"],b:0,e:"Les anges et l'Esprit y descendent, avec la permission de leur Seigneur.",s:['q:97:4']},
  {q:"Selon la sourate Al-Qadr, jusqu'à quand la Nuit du Destin est-elle paix ?",c:["Jusqu'à l'apparition de l'aube","Jusqu'à minuit","Jusqu'à la fin du Ramadan","Jusqu'à l'Aïd"],b:0,e:"« Elle est paix et salut jusqu'à l'apparition de l'aube. »",s:['q:97:5']},
  {q:"Combien de versets compte la sourate Al-Qadr ?",c:["5","7","3","10"],b:0,e:"La sourate Al-Qadr compte 5 versets.",s:['q:97:5']},
  {q:"Mille mois représentent environ combien d'années ?",c:["Plus de 83 ans","10 ans","40 ans","1 000 ans"],b:0,e:"1 000 mois ÷ 12 ≈ 83 ans et 4 mois : plus qu'une vie entière.",s:['q:97:3']},
  {q:"Quelles sont les nuits impaires des dix dernières nuits du Ramadan ?",c:["21, 23, 25, 27 et 29","20, 22, 24, 26 et 28","1, 3, 5, 7 et 9","11, 13, 15, 17 et 19"],b:0,e:"Ce sont les nuits recommandées pour chercher Laylat al-Qadr.",s:['h:qadr']},
  {q:"Quelle invocation le Prophète ﷺ a-t-il enseignée à ʿÂ'icha pour la Nuit du Destin ?",c:["« Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî »","« Bismi Llâh »","« Allâhu akbar »","« Subḥâna Llâh »"],b:0,e:"« Ô Allah, Tu es Celui qui pardonne, Tu aimes le pardon, alors pardonne-moi. »",s:['h:afw']}
 ]},
'r-aid':{titre:"L'Aïd al-Fitr",
 texte:["L'Aïd al-Fitr est la fête de la rupture du jeûne. Il a lieu le 1ᵉʳ jour du mois de Shawwâl, juste après le Ramadan.",
  "Avant de sortir pour la prière de l'Aïd, le Prophète ﷺ mangeait quelques dattes, en nombre impair. La zakat al-fitr doit être versée avant cette prière.",
  "Après l'Aïd, il est recommandé de jeûner six jours du mois de Shawwâl : avec le Ramadan, c'est comme jeûner toute l'année."],
 retenir:"1ᵉʳ Shawwâl : l'Aïd. Des dattes avant la prière, puis six jours de Shawwâl.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"Quel jour a lieu l'Aïd al-Fitr ?",c:["Le 1ᵉʳ jour de Shawwâl","Le 27 Ramadan","Le 10 Dhû l-Hijja","Le 1ᵉʳ Muharram"],b:0,e:"L'Aïd al-Fitr suit directement le mois de Ramadan.",s:['f:mois']},
  {q:"Que signifie « Aïd al-Fitr » ?",c:["La fête de la rupture du jeûne","La fête du sacrifice","La fête de l'Hégire","La fête de la naissance du Prophète ﷺ"],b:0,e:"Fitr signifie la rupture du jeûne.",s:['f:aid']},
  {q:"Que mangeait le Prophète ﷺ avant de sortir pour la prière de l'Aïd al-Fitr ?",c:["Quelques dattes","Des figues","De la viande","Rien, il jeûnait"],b:0,e:"Il ne sortait pas le jour de l'Aïd al-Fitr sans avoir mangé quelques dattes.",s:['h:aid_dattes']},
  {q:"En quel nombre le Prophète ﷺ mangeait-il les dattes le matin de l'Aïd al-Fitr ?",c:["En nombre impair","Toujours deux","Toujours sept","En nombre pair"],b:0,e:"Anas rapporte qu'il les mangeait en nombre impair.",s:['h:aid_dattes']},
  {q:"Combien de fêtes (Aïd) l'islam compte-t-il dans l'année ?",c:["2","1","3","5"],b:0,e:"L'Aïd al-Fitr et l'Aïd al-Adhâ.",s:['f:aid']},
  {q:"Selon le hadith, combien de jours de Shawwâl est-il recommandé de jeûner après le Ramadan ?",c:["6","3","10","30"],b:0,e:"Six jours de Shawwâl, consécutifs ou non.",s:['h:shawwal']},
  {q:"Selon le hadith, jeûner le Ramadan puis six jours de Shawwâl équivaut à quoi ?",c:["Jeûner toute l'année","Faire le hajj","Jeûner un mois de plus","Rien de particulier"],b:0,e:"C'est comme s'il avait jeûné toute l'année.",s:['h:shawwal']},
  {q:"Avant quelle prière faut-il avoir versé la zakat al-fitr ?",c:["La prière de l'Aïd","La prière du vendredi","La prière du Maghrib","Les tarâwîh"],b:0,e:"Elle doit être versée avant que les gens ne sortent pour la prière de l'Aïd.",s:['h:fitr']},
  {q:"Selon le verset 185 de la sourate Al-Baqara, que font les croyants une fois le nombre de jours du Ramadan accompli ?",c:["Ils proclament la grandeur d'Allah","Ils recommencent à jeûner","Ils font l'iʿtikâf","Ils partent visiter Médine"],b:0,e:"Le verset invite à proclamer la grandeur d'Allah pour la guidée reçue : c'est le takbîr de l'Aïd.",s:['q:2:185']},
  {q:"Quelle est l'autre grande fête de l'islam, célébrée pendant le pèlerinage ?",c:["L'Aïd al-Adhâ","L'Aïd al-Fitr","Le Mawlid","Le 1ᵉʳ Muharram"],b:0,e:"L'Aïd al-Adhâ, la fête du sacrifice, a lieu le 10 Dhû l-Hijja.",s:['f:aid']}
 ]},

/* ===================== PILIERS & PRIÈRE ===================== */
'p-piliers':{titre:"Les cinq piliers de l'islam",
 texte:["L'islam repose sur cinq piliers, cités dans un hadith authentique rapporté par al-Bukhari et Muslim.",
  "La shahada, l'attestation de foi. La salât, les cinq prières quotidiennes. La zakat, l'aumône obligatoire. Le hajj, le pèlerinage à La Mecque pour qui en a les moyens. Le sawm, le jeûne du Ramadan.",
  "Ces cinq piliers sont les fondations de la pratique du musulman, toute l'année."],
 retenir:"Shahada, salât, zakat, hajj, jeûne du Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"Combien de piliers compte l'islam ?",c:["5","3","4","6"],b:0,e:"L'islam repose sur cinq piliers.",s:['h:piliers']},
  {q:"Comment appelle-t-on le jeûne en arabe ?",c:["Sawm (ou siyâm)","Salât","Zakat","Hajj"],b:0,e:"Le jeûne se dit sawm ou siyâm ; c'est le mot du verset qui le prescrit.",s:['q:2:183']},
  {q:"Pour qui le pèlerinage à La Mecque (hajj) est-il obligatoire ?",c:["Pour celui qui en a les moyens, une fois dans sa vie","Pour tout le monde, chaque année","Seulement pour les hommes","Seulement pendant le Ramadan"],b:0,e:"Le hajj est obligatoire une fois dans la vie, pour qui en a la capacité physique et financière.",s:['q:3:97']},
  {q:"Combien de prières obligatoires un musulman accomplit-il chaque jour ?",c:["5","3","7","2"],b:0,e:"Fajr, Dhohr, ʿAsr, Maghrib et ʿIshâ'.",s:['h:cinq']},
  {q:"Quel est le premier pilier de l'islam ?",c:["La shahada, l'attestation de foi","Le jeûne","Le hajj","La zakat"],b:0,e:"La shahada est citée en premier dans le hadith.",s:['h:piliers']},
  {q:"Quel pilier de l'islam est l'aumône obligatoire ?",c:["La zakat","La salât","Le sawm","La shahada"],b:0,e:"La zakat est versée chaque année sur les biens qui atteignent un seuil.",s:['h:piliers']},
  {q:"Quel pilier de l'islam se pratique pendant le mois de Ramadan ?",c:["Le jeûne (sawm)","Le hajj","La zakat","La shahada"],b:0,e:"Le jeûne du Ramadan est un des cinq piliers.",s:['h:piliers']},
  {q:"Quel pilier de l'islam consiste à se rendre à La Mecque ?",c:["Le hajj","La salât","Le sawm","La zakat"],b:0,e:"Le hajj est le pèlerinage à la Maison sacrée.",s:['q:3:97']},
  {q:"Selon le hadith, combien de fois dans la vie le hajj est-il obligatoire ?",c:["Une seule fois","Chaque année","Trois fois","Sept fois"],b:0,e:"Le Prophète ﷺ a précisé qu'il n'était pas obligatoire chaque année.",s:['h:hajj_une']},
  {q:"Quel Compagnon a rapporté le hadith des cinq piliers de l'islam ?",c:["ʿAbdallah ibn ʿUmar","Abû Bakr","Bilâl","Khâlid ibn al-Walîd"],b:0,e:"Le hadith est rapporté par Ibn ʿUmar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"La shahada, l'attestation de foi",
 texte:["La shahada est l'attestation de foi : « Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh ».",
  "Elle signifie : « J'atteste qu'il n'y a de divinité qu'Allah, et j'atteste que Muhammad est le Messager d'Allah. »",
  "C'est le premier pilier : par elle, on entre en islam. Elle affirme l'unicité d'Allah, le tawḥîd, résumée dans la sourate Al-Ikhlâs."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Quel pilier de l'islam est l'attestation de foi ?",c:["La shahada","La salât","La zakat","Le hajj"],b:0,e:"La shahada est le premier pilier.",s:['h:piliers']},
  {q:"Que signifie « lâ ilâha illâ Llâh » ?",c:["Il n'y a de divinité qu'Allah","Allah est le plus grand","Gloire à Allah","Au nom d'Allah"],b:0,e:"C'est la première partie de la shahada.",s:['q:47:19']},
  {q:"Que signifie « Muḥammadun rasûlu Llâh » ?",c:["Muhammad est le Messager d'Allah","Muhammad est un ange","Muhammad est le premier homme","Muhammad est un roi"],b:0,e:"C'est la seconde partie de la shahada.",s:['q:48:29']},
  {q:"Comment appelle-t-on la croyance en l'unicité d'Allah ?",c:["Le tawḥîd","Le hajj","La sunna","Le fiqh"],b:0,e:"Le tawḥîd est le cœur de la foi musulmane.",s:['q:112:1']},
  {q:"Quelle sourate résume l'unicité d'Allah en quatre versets ?",c:["Al-Ikhlâs","Al-Fâtiha","Al-Kawthar","An-Nâs"],b:0,e:"La sourate 112, Al-Ikhlâs.",s:['q:112:1']},
  {q:"De combien de parties se compose la shahada ?",c:["Deux : l'unicité d'Allah et le message de Muhammad ﷺ","Une seule","Cinq","Sept"],b:0,e:"On atteste l'unicité d'Allah, puis que Muhammad ﷺ est Son Messager.",s:['h:piliers']},
  {q:"Selon la sourate Al-Ikhlâs, Allah a-t-Il engendré ou a-t-Il été engendré ?",c:["Ni l'un ni l'autre","Les deux","Il a engendré","Il a été engendré"],b:0,e:"« Il n'a jamais engendré, n'a pas été engendré non plus. »",s:['q:112:3']},
  {q:"Que signifie « Ash-hadu » au début de la shahada ?",c:["J'atteste","Je prie","Je jeûne","Je pardonne"],b:0,e:"Ash-hadu signifie « j'atteste, je témoigne ».",s:['f:shahada']},
  {q:"Que fait une personne pour entrer en islam ?",c:["Elle prononce la shahada avec conviction","Elle jeûne un mois","Elle fait le hajj","Elle apprend l'arabe"],b:0,e:"La shahada prononcée sincèrement fait entrer en islam.",s:['f:shahada']},
  {q:"Que dit le Coran de Muhammad ﷺ dans la sourate Âl ʿImrân, verset 144 ?",c:["Il n'est qu'un messager, d'autres messagers sont passés avant lui","Il est éternel","Il est un ange","Il est le premier prophète"],b:0,e:"Muhammad ﷺ est un être humain et un messager, comme ceux qui l'ont précédé.",s:['q:3:144']}
 ]},
'p-priere':{titre:"La prière, cinq rendez-vous par jour",
 texte:["Le musulman prie cinq fois par jour : Fajr à l'aube, Dhohr à midi, ʿAsr l'après-midi, Maghrib au coucher du soleil et ʿIshâ' la nuit.",
  "Chaque prière compte un nombre précis d'unités (rakʿât) : 2 pour le Fajr, 4 pour le Dhohr, 4 pour l'ʿAsr, 3 pour le Maghrib et 4 pour l'ʿIshâ'.",
  "On prie tourné vers la Kaaba, à La Mecque : c'est la qibla. L'heure de chaque prière est annoncée par l'adhân. Le vendredi, la prière du Dhohr est remplacée par la prière du vendredi (Jumuʿa)."],
 retenir:"Fajr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshâ' 4 — tourné vers la qibla.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"Combien d'unités (rakʿât) compte la prière obligatoire du Fajr ?",c:["2","3","4","1"],b:0,e:"La prière du Fajr compte 2 rakʿât.",s:['f:rakat']},
  {q:"Combien d'unités (rakʿât) compte la prière obligatoire du Maghrib ?",c:["3","2","4","5"],b:0,e:"Le Maghrib est la seule prière obligatoire de 3 rakʿât.",s:['f:rakat']},
  {q:"Vers quelle direction les musulmans se tournent-ils pour prier ?",c:["Vers la Kaaba, à La Mecque","Vers Jérusalem","Vers Médine","Vers l'est"],b:0,e:"Cette direction s'appelle la qibla.",s:['q:2:144']},
  {q:"Comment s'appelle l'appel qui annonce l'heure de la prière ?",c:["L'adhân","L'iqâma","Le duʿâ'","Le dhikr"],b:0,e:"L'adhân annonce l'heure ; l'iqâma annonce le début de la prière en groupe.",s:['h:adhan']},
  {q:"Comment s'appelle la prière obligatoire faite à l'aube ?",c:["Le Fajr","Le Dhohr","L'ʿAsr","L'ʿIshâ'"],b:0,e:"Le Fajr se prie entre l'aube et le lever du soleil.",s:['f:rakat']},
  {q:"Combien d'unités (rakʿât) compte la prière obligatoire du Dhohr ?",c:["4","2","3","5"],b:0,e:"Le Dhohr compte 4 rakʿât.",s:['f:rakat']},
  {q:"Combien d'unités (rakʿât) obligatoires compte-t-on au total dans les cinq prières d'une journée ?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rakʿât.",s:['f:rakat']},
  {q:"Selon le Coran, comment la prière a-t-elle été prescrite aux croyants ?",c:["À des heures déterminées","Une fois par semaine","Quand on le souhaite","Seulement pendant le Ramadan"],b:0,e:"« La Salât demeure, pour les croyants, une prescription, à des temps déterminés. »",s:['q:4:103']},
  {q:"Quelle prière collective a lieu chaque vendredi à la place du Dhohr ?",c:["La prière du vendredi (Jumuʿa)","La prière de l'Aïd","Les tarâwîh","La prière de la pluie"],b:0,e:"Le Coran appelle à se rendre au rappel d'Allah le vendredi.",s:['q:62:9']},
  {q:"Selon le hadith, lors de quel événement les cinq prières ont-elles été prescrites ?",c:["Le Voyage nocturne (al-Isrâ' wa l-Miʿrâj)","La bataille de Badr","L'Hégire","La conquête de La Mecque"],b:0,e:"Cinquante prières furent prescrites, puis ramenées à cinq.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"Les ablutions et la Fâtiha",
 texte:["Avant de prier, le musulman se purifie avec de l'eau : ce sont les ablutions (wudû'). Sans eau, on fait le tayammum avec de la terre propre.",
  "On lave le visage, les mains et les avant-bras jusqu'aux coudes, on passe les mains mouillées sur la tête, puis on lave les pieds jusqu'aux chevilles.",
  "Dans chaque unité de la prière, on récite la sourate Al-Fâtiha, « l'Ouverture », la première sourate du Coran, qui compte 7 versets."],
 retenir:"Pas de prière sans ablutions, pas de prière sans la Fâtiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"Comment s'appelle la purification faite avec de l'eau avant la prière ?",c:["Les ablutions (wudû')","Le jeûne","La zakat","L'iʿtikâf"],b:0,e:"Le wudû' purifie avant la prière.",s:['q:5:6']},
  {q:"Quelle sourate est récitée dans chaque unité (rakʿa) de la prière ?",c:["Al-Fâtiha","Al-Ikhlâs","Al-Baqara","Yâ-Sîn"],b:0,e:"Al-Fâtiha, « l'Ouverture », est récitée dans chaque rakʿa.",s:['h:fatiha']},
  {q:"Par quelle phrase commence la sourate Al-Fâtiha ?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"« Au nom d'Allah, le Tout Miséricordieux, le Très Miséricordieux. »",s:['q:1:1']},
  {q:"Selon le Coran, jusqu'où lave-t-on les bras pendant les ablutions ?",c:["Jusqu'aux coudes","Jusqu'aux poignets","Jusqu'aux épaules","Seulement les doigts"],b:0,e:"Le verset 6 de la sourate Al-Mâ'ida le précise.",s:['q:5:6']},
  {q:"Selon le Coran, que fait-on sur la tête pendant les ablutions ?",c:["On passe les mains mouillées dessus","On la lave entièrement trois fois","On la couvre d'un turban","On verse de l'eau sur la nuque"],b:0,e:"C'est le masḥ : passer les mains mouillées sur la tête.",s:['q:5:6']},
  {q:"Que fait-on quand on ne trouve pas d'eau pour se purifier avant la prière ?",c:["Le tayammum, avec de la terre propre","On ne prie pas","On attend le lendemain","On prie sans purification"],b:0,e:"Le même verset prévoit le tayammum quand l'eau manque.",s:['q:5:6']},
  {q:"Selon le hadith, Allah accepte-t-il la prière de celui qui a perdu ses ablutions sans les refaire ?",c:["Non, pas avant qu'il refasse ses ablutions","Oui, toujours","Oui, le vendredi","Seulement la prière du Fajr"],b:0,e:"La prière n'est acceptée qu'après avoir refait ses ablutions.",s:['h:wudu']},
  {q:"Combien de versets compte la sourate Al-Fâtiha ?",c:["7","5","10","3"],b:0,e:"Elle est appelée « les sept versets répétés ».",s:['q:15:87']},
  {q:"Que signifie « Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn » ?",c:["Louange à Allah, Seigneur de l'univers","Allah est le plus grand","Il n'y a de divinité qu'Allah","Je cherche refuge auprès d'Allah"],b:0,e:"C'est le 2ᵉ verset de la Fâtiha.",s:['q:1:2']},
  {q:"Selon le hadith, que vaut la prière de celui qui ne récite pas la Fâtiha ?",c:["Elle n'est pas valable","Elle compte double","Elle est valable","Elle compte à moitié"],b:0,e:"« Pas de prière pour celui qui ne récite pas la Fâtiha. »",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"La zakat, l'aumône obligatoire",
 texte:["La zakat est l'aumône obligatoire, l'un des cinq piliers de l'islam. Son nom évoque la purification et la croissance : elle purifie les biens et aide les plus démunis.",
  "Elle concerne celui dont l'épargne atteint un seuil minimum (le niṣâb) et reste en sa possession pendant une année lunaire complète. Pour l'argent, elle est de 2,5 %.",
  "Le Coran cite huit catégories de bénéficiaires, dont les pauvres et les nécessiteux. La sadaqa, elle, est une aumône volontaire, possible à tout moment."],
 retenir:"Zakat : 2,5 % de l'épargne qui atteint le niṣâb pendant un an lunaire.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Quel pilier de l'islam est l'aumône obligatoire ?",c:["La zakat","La sadaqa","Le hajj","Le sawm"],b:0,e:"La zakat est obligatoire ; la sadaqa est volontaire.",s:['h:piliers']},
  {q:"Quel est le taux de la zakat sur l'argent épargné ?",c:["2,5 %","10 %","20 %","5 %"],b:0,e:"Soit un quarantième de l'épargne.",s:['f:zakat']},
  {q:"Comment appelle-t-on le seuil minimum de richesse à partir duquel la zakat est due ?",c:["Le niṣâb","Le sâʿ","La fidya","Le ḥawl"],b:0,e:"En dessous du niṣâb, la zakat n'est pas obligatoire.",s:['f:zakat']},
  {q:"Pendant combien de temps l'épargne doit-elle être possédée pour que la zakat soit due ?",c:["Une année lunaire","Un mois","Dix ans","Le mois de Ramadan seulement"],b:0,e:"C'est le ḥawl : une année lunaire complète.",s:['f:zakat']},
  {q:"Selon le Coran, combien de catégories de personnes peuvent recevoir la zakat ?",c:["8","5","3","12"],b:0,e:"Le verset 60 de la sourate At-Tawba en cite huit.",s:['q:9:60']},
  {q:"Lesquels font partie des bénéficiaires de la zakat cités dans le Coran ?",c:["Les pauvres et les nécessiteux","Les plus riches","Les commerçants","Les imams des mosquées"],b:0,e:"Les pauvres et les nécessiteux sont cités en premier.",s:['q:9:60']},
  {q:"Quelle est la différence entre la zakat et la sadaqa ?",c:["La zakat est obligatoire, la sadaqa est volontaire","Il n'y en a aucune","La sadaqa est obligatoire","La zakat est interdite"],b:0,e:"La sadaqa peut se donner à tout moment et en toute quantité.",s:['f:zakat']},
  {q:"Dans le Coran, avec quel acte la zakat est-elle très souvent citée ?",c:["La prière","Le jeûne","Le pèlerinage","Les ablutions"],b:0,e:"« Et accomplissez la Salât, et acquittez la Zakât » : la formule revient de nombreuses fois.",s:['q:2:43']},
  {q:"Dans l'ordre du hadith des piliers, à quelle place vient la zakat ?",c:["La 3ᵉ","La 1ʳᵉ","La 5ᵉ","La 2ᵉ"],b:0,e:"Shahada, prière, zakat, hajj, jeûne du Ramadan.",s:['h:piliers']},
  {q:"Qu'évoque le mot « zakat » en arabe ?",c:["La purification et la croissance","La patience","La victoire","La lumière"],b:0,e:"Le Coran dit que l'aumône purifie (tuṭahhiruhum) et fait croître en bien (tuzakkîhim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"Le hajj, le pèlerinage",
 texte:["Le hajj est le pèlerinage à La Mecque, l'un des cinq piliers de l'islam. Il est obligatoire une fois dans la vie pour qui en a les moyens physiques et financiers.",
  "Il a lieu pendant le mois de Dhû l-Hijja. Le pèlerin entre en état de sacralisation (iḥrâm), fait sept tours autour de la Kaaba (ṭawâf) et sept parcours entre Ṣafâ et Marwa (saʿy). Le moment le plus important est la station à ʿArafa, le 9 Dhû l-Hijja.",
  "Le lendemain, les musulmans du monde entier célèbrent l'Aïd al-Adhâ, la fête du sacrifice, en souvenir d'Ibrahim."],
 retenir:"Une fois dans la vie. ʿArafa le 9 Dhû l-Hijja, l'Aïd al-Adhâ le 10.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"Dans quelle ville se fait le hajj ?",c:["La Mecque","Médine","Jérusalem","Taïf"],b:0,e:"Le hajj se fait à La Mecque et dans ses environs.",s:['q:3:97']},
  {q:"Pendant quel mois du calendrier musulman a lieu le hajj ?",c:["Dhû l-Hijja","Ramadan","Muharram","Shawwâl"],b:0,e:"Le hajj se déroule du 8 au 13 Dhû l-Hijja.",s:['f:hajj']},
  {q:"Selon le hadith, quel est l'élément le plus important du hajj ?",c:["La station à ʿArafa","La prière à la mosquée al-Aqṣâ","La visite de Médine","La visite de la grotte de Hira"],b:0,e:"« Le hajj, c'est ʿArafa. »",s:['h:arafa']},
  {q:"Quelle fête est célébrée le lendemain du jour de ʿArafa ?",c:["L'Aïd al-Adhâ","L'Aïd al-Fitr","Le Mawlid","Le 1ᵉʳ Muharram"],b:0,e:"Le 10 Dhû l-Hijja, c'est l'Aïd al-Adhâ.",s:['f:hajj']},
  {q:"Selon le hadith, comment revient le pèlerin qui accomplit le hajj sans péché ni grossièreté ?",c:["Comme au jour où sa mère l'a mis au monde","Plus riche","Dispensé de jeûner","Avec le titre de ḥâjj, sans autre récompense"],b:0,e:"Il revient pur de ses péchés.",s:['h:hajj_pardon']},
  {q:"Quel prophète a reçu l'ordre d'appeler les gens au pèlerinage ?",c:["Ibrahim","Mûsâ","Nûh","Yûsuf"],b:0,e:"Allah a ordonné à Ibrahim d'appeler les gens au hajj.",s:['q:22:27']},
  {q:"Comment s'appelle l'état de sacralisation dans lequel entre le pèlerin ?",c:["L'iḥrâm","Le wudû'","L'iʿtikâf","Le tayammum"],b:0,e:"Les hommes portent deux pièces de tissu blanc non cousues.",s:['f:hajj']},
  {q:"Comment s'appellent les sept tours effectués autour de la Kaaba ?",c:["Le ṭawâf","Le saʿy","La rakʿa","Le dhikr"],b:0,e:"Le ṭawâf se fait en sept tours, la Kaaba à sa gauche.",s:['f:hajj']},
  {q:"Entre quelles deux collines le pèlerin fait-il sept parcours ?",c:["Ṣafâ et Marwa","ʿArafa et Minâ","Uhud et Thawr","Hira et Thawr"],b:0,e:"Le Coran cite Ṣafâ et Marwa parmi les rites d'Allah.",s:['q:2:158']},
  {q:"En souvenir de quel prophète les musulmans sacrifient-ils une bête le jour de l'Aïd al-Adhâ ?",c:["Ibrahim","ʿÎsâ","Mûsâ","Dâwûd"],b:0,e:"Allah racheta le fils d'Ibrahim par une immolation généreuse.",s:['q:37:107']}
 ]},

/* ===================== CORAN ===================== */
'c-coran':{titre:"Le Coran, parole d'Allah",
 texte:["Le Coran est la parole d'Allah, révélée en arabe au Prophète Muhammad ﷺ par l'intermédiaire de l'ange Jibrîl (Gabriel).",
  "La première révélation a eu lieu dans la grotte de Hira, près de La Mecque, quand le Prophète ﷺ avait 40 ans. Les premiers mots révélés commencent par « Iqra' » : « Lis ! ».",
  "La révélation a duré environ 23 ans. Le Coran compte 114 sourates ; Allah s'est engagé à le préserver."],
 retenir:"114 sourates, révélées en 23 ans. Premier mot : « Iqra' », « Lis ! ».",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"Combien de sourates compte le Coran ?",c:["114","99","120","30"],b:0,e:"Le Coran compte 114 sourates.",s:['f:coran']},
  {q:"Quel ange a transmis le Coran au Prophète Muhammad ﷺ ?",c:["Jibrîl (Gabriel)","Mikâ'îl","Isrâfîl","Mâlik"],b:0,e:"C'est l'ange Jibrîl qui a transmis la révélation.",s:['q:2:97']},
  {q:"Dans quelle grotte le Prophète ﷺ a-t-il reçu la première révélation du Coran ?",c:["La grotte de Hira","La grotte de Thawr","Une grotte de Médine","Une grotte de Jérusalem"],b:0,e:"La grotte de Hira se trouve sur le Jabal an-Nour, près de La Mecque.",s:['h:hira']},
  {q:"Que signifie « Iqra' », le premier mot révélé du Coran ?",c:["Lis !","Prie !","Écoute !","Jeûne !"],b:0,e:"C'est le début de la sourate Al-ʿAlaq (96).",s:['q:96:1']},
  {q:"Sur combien d'années environ le Coran a-t-il été révélé ?",c:["23 ans","1 an","40 ans","10 ans"],b:0,e:"Environ 13 ans à La Mecque et 10 ans à Médine.",s:['h:vie']},
  {q:"En combien de parties (juz') le Coran est-il divisé pour sa lecture ?",c:["30","114","7","12"],b:0,e:"Trente parties : par exemple une par jour pendant le Ramadan.",s:['f:coran']},
  {q:"Dans quelle langue le Coran a-t-il été révélé ?",c:["En arabe","En hébreu","En persan","En araméen"],b:0,e:"« Nous l'avons fait descendre, un Coran en langue arabe. »",s:['q:12:2']},
  {q:"Selon le Coran, qui assure la préservation du Coran ?",c:["Allah","Les savants seulement","Les califes","Personne"],b:0,e:"« C'est Nous qui avons fait descendre le Coran, et c'est Nous qui en sommes gardien. »",s:['q:15:9']},
  {q:"Quel âge avait le Prophète ﷺ lors de la première révélation ?",c:["40 ans","25 ans","63 ans","13 ans"],b:0,e:"Il a commencé à recevoir la révélation à 40 ans.",s:['h:vie']},
  {q:"Comment appelle-t-on un verset du Coran en arabe ?",c:["Une âya","Une sourate","Un juz'","Un hadith"],b:0,e:"Un verset se dit âya ; un chapitre, sourate.",s:['f:coran']}
 ]},
'c-sourates':{titre:"Les sourates",
 texte:["Le Coran est composé de 114 sourates de longueurs très différentes. Chacune commence par la basmala, sauf la sourate At-Tawba.",
  "La première est Al-Fâtiha, « l'Ouverture ». La plus longue est Al-Baqara, « la Vache », avec 286 versets. La plus courte est Al-Kawthar, avec 3 versets. La dernière est An-Nâs, « les Hommes ».",
  "Les sourates révélées avant l'Hégire sont dites mecquoises, celles révélées après, médinoises."],
 retenir:"Première : Al-Fâtiha. Plus longue : Al-Baqara. Plus courte : Al-Kawthar. Dernière : An-Nâs.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"Quelle est la première sourate du Coran ?",c:["Al-Fâtiha","Al-Baqara","An-Nâs","Al-ʿAlaq"],b:0,e:"Al-Fâtiha ouvre le Coran. Al-ʿAlaq contient les premiers versets révélés, mais elle est la sourate 96.",s:['q:1:1']},
  {q:"Quelle est la plus longue sourate du Coran ?",c:["Al-Baqara","Al-Fâtiha","Al-Kawthar","Yâ-Sîn"],b:0,e:"Al-Baqara, la sourate 2, compte 286 versets.",s:['f:coran']},
  {q:"Quelle est la plus courte sourate du Coran ?",c:["Al-Kawthar","Al-Ikhlâs","An-Nâs","Al-ʿAsr"],b:0,e:"Al-Kawthar, la sourate 108, compte 3 versets.",s:['q:108:1']},
  {q:"Quelle est la dernière sourate du Coran ?",c:["An-Nâs","Al-Falaq","Al-Ikhlâs","Al-Fâtiha"],b:0,e:"An-Nâs, « les Hommes », est la sourate 114.",s:['q:114:1']},
  {q:"Quelle sourate commence par « Qul huwa Llâhu aḥad » ?",c:["Al-Ikhlâs","An-Nâs","Al-Falaq","Al-Kâfirûn"],b:0,e:"« Dis : Il est Allah, Unique. »",s:['q:112:1']},
  {q:"Quelle sourate contient le verset « C'est le Livre au sujet duquel il n'y a aucun doute » ?",c:["Al-Baqara","Al-Fâtiha","Maryam","Yâ-Sîn"],b:0,e:"C'est le 2ᵉ verset de la sourate Al-Baqara.",s:['q:2:2']},
  {q:"Quelle sourate porte le nom de la mère de ʿÎsâ (Jésus) ?",c:["Maryam","Âl ʿImrân","An-Nisâ'","Tâ-Hâ"],b:0,e:"La sourate 19 porte le nom de Maryam.",s:['q:19:16']},
  {q:"Quelle est la seule sourate qui ne commence pas par « Bismi Llâhi r-Raḥmâni r-Raḥîm » ?",c:["At-Tawba (sourate 9)","Al-Fâtiha","An-Nâs","Al-Baqara"],b:0,e:"At-Tawba est la seule des 114 sourates sans basmala au début.",s:['f:tawba']},
  {q:"Comment appelle-t-on la formule « Bismi Llâhi r-Raḥmâni r-Raḥîm » ?",c:["La basmala","La shahada","Le takbîr","La talbiya"],b:0,e:"Elle signifie : « Au nom d'Allah, le Tout Miséricordieux, le Très Miséricordieux ».",s:['q:1:1']},
  {q:"Comment appelle-t-on les sourates révélées à La Mecque, avant l'Hégire ?",c:["Les sourates mecquoises","Les sourates médinoises","Les sourates longues","Les sourates de Taïf"],b:0,e:"Celles révélées après l'Hégire sont dites médinoises.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlâs et le verset du Trône",
 texte:["La sourate Al-Ikhlâs (112) résume la foi en l'unicité d'Allah : Il est Unique, Il n'a pas engendré et n'a pas été engendré, et nul ne Lui est égal.",
  "Le Prophète ﷺ a dit qu'elle équivaut à un tiers du Coran.",
  "Le verset du Trône, Âyat al-Kursî (sourate 2, verset 255), est le plus grand verset du Coran. Il décrit la vie, la science et la puissance d'Allah."],
 retenir:"Al-Ikhlâs vaut un tiers du Coran. Âyat al-Kursî est le plus grand verset.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"Que signifie « Qul huwa Llâhu aḥad » ?",c:["Dis : Il est Allah, Unique","Au nom d'Allah","Allah est le plus grand","Gloire à Allah"],b:0,e:"C'est le premier verset de la sourate Al-Ikhlâs.",s:['q:112:1']},
  {q:"Selon le hadith, la sourate Al-Ikhlâs équivaut à quelle part du Coran ?",c:["Un tiers","La moitié","Un dixième","Le Coran entier"],b:0,e:"Le Prophète ﷺ a dit qu'elle équivaut à un tiers du Coran.",s:['h:ikhlas']},
  {q:"Combien de versets compte la sourate Al-Ikhlâs ?",c:["4","7","3","5"],b:0,e:"La sourate Al-Ikhlâs compte 4 versets.",s:['q:112:4']},
  {q:"Selon la sourate Al-Ikhlâs, quelqu'un est-il égal à Allah ?",c:["Non, nul n'est égal à Lui","Oui, les anges","Oui, les prophètes","Oui, les djinns"],b:0,e:"« Et nul n'est égal à Lui. »",s:['q:112:4']},
  {q:"Selon le hadith, quel est le plus grand verset du Coran ?",c:["Âyat al-Kursî, le verset du Trône","Le premier verset de la Fâtiha","Le dernier verset du Coran","Le verset de la lumière"],b:0,e:"Ubayy ibn Kaʿb l'a dit au Prophète ﷺ, qui l'a approuvé.",s:['h:kursi']},
  {q:"Dans quelle sourate se trouve Âyat al-Kursî ?",c:["Al-Baqara, verset 255","Al-Fâtiha, verset 1","Yâ-Sîn, verset 1","Al-Ikhlâs, verset 2"],b:0,e:"Le verset du Trône est le 255ᵉ verset de la sourate Al-Baqara.",s:['q:2:255']},
  {q:"Selon Âyat al-Kursî, Allah est-Il saisi par la somnolence ou le sommeil ?",c:["Non, ni somnolence ni sommeil ne Le saisissent","Oui, la nuit","Oui, parfois","Seulement le sommeil"],b:0,e:"Allah est le Vivant, Celui qui subsiste par Lui-même.",s:['q:2:255']},
  {q:"Que signifie « Allâhu ṣ-ṣamad » dans la sourate Al-Ikhlâs ?",c:["Allah est Celui dont tous ont besoin, et qui n'a besoin de personne","Allah est le Créateur du ciel","Allah est le Pardonneur","Allah est le Juge"],b:0,e:"Aṣ-Ṣamad est l'un des noms d'Allah.",s:['q:112:2']},
  {q:"Que signifie le nom de la sourate « Al-Ikhlâs » ?",c:["Le monothéisme pur, la sincérité","L'aube","La victoire","Les hommes"],b:0,e:"Elle purifie la foi de toute association.",s:['f:ikhlas']},
  {q:"Selon Âyat al-Kursî, que cède Allah à Ses créatures de Sa science ?",c:["Seulement ce qu'Il veut","Toute Sa science","Rien du tout","La moitié"],b:0,e:"« Et, de Sa science, ils n'embrassent que ce qu'Il veut. »",s:['q:2:255']}
 ]},

/* ===================== PROPHÈTES ===================== */
'pr-adam':{titre:"Adam et Nûh",
 texte:["Adam est le premier homme et le premier prophète. Allah lui apprit le nom de toute chose, puis ordonna aux anges de se prosterner devant lui. Iblîs refusa par orgueil.",
  "Nûh (Noé) appela son peuple à adorer Allah seul pendant 950 ans. Peu de gens le suivirent, pas même son propre fils.",
  "Sur l'ordre d'Allah, Nûh construisit l'arche, qui le sauva du déluge avec les croyants et des couples d'animaux."],
 retenir:"Adam, le premier homme. Nûh, 950 ans de prédication, et l'arche.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Qui est le premier prophète de l'humanité ?",c:["Adam","Nûh (Noé)","Ibrahim (Abraham)","Mûsâ (Moïse)"],b:0,e:"Adam est le premier homme et le premier prophète.",s:['q:2:31']},
  {q:"Qu'Allah a-t-Il appris à Adam ?",c:["Le nom de toute chose","Le Coran par cœur","La langue des anges seulement","Les noms des prophètes seulement"],b:0,e:"« Et Il apprit à Adam tous les noms. »",s:['q:2:31']},
  {q:"Qui a refusé de se prosterner devant Adam ?",c:["Iblîs","Jibrîl","Mikâ'îl","Tous les anges"],b:0,e:"Les anges se prosternèrent, sauf Iblîs.",s:['q:2:34']},
  {q:"Pourquoi Iblîs a-t-il refusé de se prosterner devant Adam ?",c:["Par orgueil","Par oubli","Par peur","Parce qu'il n'avait pas entendu l'ordre"],b:0,e:"Il refusa, s'enfla d'orgueil et fut parmi les mécréants.",s:['q:2:34']},
  {q:"Où Adam et son épouse vivaient-ils avant de descendre sur terre ?",c:["Au Paradis","À La Mecque","En Égypte","À Jérusalem"],b:0,e:"« Habite le Paradis, toi et ton épouse. »",s:['q:2:35']},
  {q:"Quel prophète a construit l'arche sur l'ordre d'Allah ?",c:["Nûh (Noé)","Yûnus (Jonas)","Sulaymân (Salomon)","ʿÎsâ (Jésus)"],b:0,e:"Nûh a construit l'arche sous les yeux d'Allah et selon Sa révélation.",s:['q:11:37']},
  {q:"Selon le Coran, combien de temps Nûh est-il resté parmi son peuple ?",c:["950 ans","40 ans","100 ans","313 ans"],b:0,e:"« Mille ans moins cinquante années. »",s:['q:29:14']},
  {q:"Qui fut sauvé dans l'arche de Nûh ?",c:["Nûh, les croyants et des couples d'animaux","Tout son peuple","Seulement les animaux","Personne"],b:0,e:"Allah ordonna d'y faire monter un couple de chaque espèce, sa famille et les croyants.",s:['q:11:40']},
  {q:"Le fils de Nûh est-il monté dans l'arche ?",c:["Non, il a refusé et a été englouti","Oui, le premier","Oui, à la fin","Il n'avait pas de fils"],b:0,e:"Il pensa se réfugier sur une montagne, mais les vagues l'emportèrent.",s:['q:11:43']},
  {q:"Comment s'appelle l'épouse d'Adam, selon la tradition musulmane ?",c:["Hawwâ' (Ève)","Maryam","Âsiya","Hâjar"],b:0,e:"Le Coran la mentionne sans la nommer ; son nom vient de la Sunna.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, l'ami d'Allah",
 texte:["Ibrahim (Abraham) refusa d'adorer les idoles de son peuple. On le jeta dans un grand feu, mais Allah ordonna au feu d'être fraîcheur et paix pour lui.",
  "Allah l'a pris pour ami intime (khalîl). Il est le père de deux prophètes : Ismaʿîl et Isḥâq.",
  "Avec son fils Ismaʿîl, il éleva les fondations de la Kaaba. Le sacrifice de l'Aïd al-Adhâ rappelle son obéissance à Allah."],
 retenir:"Ibrahim, l'ami d'Allah, sauvé du feu, bâtisseur de la Kaaba avec Ismaʿîl.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Quel prophète a élevé les fondations de la Kaaba avec son fils Ismaʿîl ?",c:["Ibrahim (Abraham)","Mûsâ (Moïse)","Dâwûd (David)","Adam"],b:0,e:"Ibrahim et son fils Ismaʿîl ont élevé les fondations de la Kaaba.",s:['q:2:127']},
  {q:"Qu'arriva-t-il à Ibrahim quand son peuple le jeta dans le feu ?",c:["Allah rendit le feu frais et sans danger pour lui","Il s'enfuit","Il fut blessé","Il fut sauvé par la pluie"],b:0,e:"« Ô feu, sois pour Abraham une fraîcheur salutaire. »",s:['q:21:69']},
  {q:"Quel titre le Coran donne-t-il au prophète Ibrahim ?",c:["L'ami intime d'Allah (Khalîl)","Le sceau des prophètes","Celui à qui Allah a parlé","L'Esprit d'Allah"],b:0,e:"« Et Allah avait pris Abraham pour ami privilégié. »",s:['q:4:125']},
  {q:"Quels sont les deux fils prophètes d'Ibrahim ?",c:["Ismaʿîl et Isḥâq","Mûsâ et Hârûn","Dâwûd et Sulaymân","Yaḥyâ et ʿÎsâ"],b:0,e:"Ibrahim remercia Allah de lui avoir donné Ismaʿîl et Isḥâq dans sa vieillesse.",s:['q:14:39']},
  {q:"Que faisait le peuple d'Ibrahim, ce qu'il refusait ?",c:["Adorer des statues","Jeûner","Faire l'aumône","Faire le pèlerinage"],b:0,e:"Il leur demanda : « Que sont ces statues auxquelles vous vous attachez ? »",s:['q:21:52']},
  {q:"Par quoi Allah racheta-t-Il le fils d'Ibrahim au moment du sacrifice ?",c:["Par une immolation généreuse (une bête à sacrifier)","Par une aumône d'or","Par le jeûne de son père","Par une prière de nuit"],b:0,e:"La tradition précise qu'il s'agissait d'un bélier.",s:['q:37:107']},
  {q:"Quelle fête rappelle l'obéissance d'Ibrahim à Allah ?",c:["L'Aïd al-Adhâ","L'Aïd al-Fitr","Le 1ᵉʳ Muharram","Le Mawlid"],b:0,e:"Le sacrifice de l'Aïd al-Adhâ commémore son épreuve.",s:['q:37:107']},
  {q:"Selon le Coran, comment est décrit Ibrahim ?",c:["Un croyant monothéiste (ḥanîf), ni juif ni chrétien","Un roi de Babylone","Un ange","Un poète"],b:0,e:"Il était entièrement soumis à Allah.",s:['q:3:67']},
  {q:"Quel fils a aidé Ibrahim à élever les fondations de la Kaaba ?",c:["Ismaʿîl","Isḥâq","Yaʿqûb","Yûsuf"],b:0,e:"Ibrahim et Ismaʿîl élevaient ensemble les fondations de la Maison.",s:['q:2:127']},
  {q:"Selon le Coran, quelle est la première Maison de culte établie pour les hommes ?",c:["Celle de Bakka (La Mecque)","Celle de Jérusalem","Celle de Médine","Celle de Taïf"],b:0,e:"Bakka est un nom de La Mecque.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yûnus, Yûsuf et Sulaymân",
 texte:["Yûnus (Jonas) fut avalé par un gros poisson. Dans les ténèbres, il invoqua Allah, qui le sauva de l'angoisse.",
  "L'histoire de Yûsuf (Joseph), trahi par ses frères puis devenu ministre en Égypte, occupe toute la sourate 12 : « le meilleur récit ».",
  "Sulaymân (Salomon), fils de Dâwûd, reçut un royaume immense et comprenait le langage des oiseaux et des fourmis."],
 retenir:"Yûnus et le poisson. Yûsuf, sourate 12. Sulaymân et le langage des animaux.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Quel prophète a été avalé par un gros poisson ?",c:["Yûnus (Jonas)","Yûsuf (Joseph)","Ayyûb (Job)","Lût (Loth)"],b:0,e:"Yûnus fut avalé par le poisson, puis Allah le sauva.",s:['q:37:142']},
  {q:"Quelle sourate du Coran raconte en entier l'histoire du prophète Yûsuf (Joseph) ?",c:["La sourate 12, Yûsuf","La sourate 1, Al-Fâtiha","La sourate 36, Yâ-Sîn","La sourate 112, Al-Ikhlâs"],b:0,e:"La sourate 12 porte son nom.",s:['q:12:3']},
  {q:"Quel prophète comprenait le langage des fourmis ?",c:["Sulaymân (Salomon)","Sâliḥ","Hûd","Zakariyyâ"],b:0,e:"Sulaymân entendit une fourmi avertir les autres, et il sourit de ses paroles.",s:['q:27:18']},
  {q:"Quelle invocation Yûnus a-t-il prononcée dans le ventre du poisson ?",c:["« Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn »","« Bismi Llâh »","« Allâhu akbar »","« Rabbanâ âtinâ »"],b:0,e:"« Pas de divinité à part Toi ! Pureté à Toi ! J'ai été vraiment du nombre des injustes. »",s:['q:21:87']},
  {q:"Comment Allah a-t-Il répondu à l'invocation de Yûnus ?",c:["Il le sauva de l'angoisse","Il le laissa dans le poisson","Il le laissa trois ans dans le poisson","Il ne répondit pas"],b:0,e:"« Nous l'exauçâmes et le sauvâmes de l'angoisse. »",s:['q:21:88']},
  {q:"Dans son rêve d'enfant, combien d'étoiles Yûsuf a-t-il vues se prosterner devant lui ?",c:["Onze, avec le soleil et la lune","Sept","Douze","Une seule"],b:0,e:"Onze étoiles, le soleil et la lune.",s:['q:12:4']},
  {q:"Qui a jeté Yûsuf au fond d'un puits ?",c:["Ses frères","Pharaon","Des marchands","Son père"],b:0,e:"Ses frères, jaloux, décidèrent de le jeter au fond du puits.",s:['q:12:15']},
  {q:"Comment le Coran appelle-t-il l'histoire de Yûsuf ?",c:["Le meilleur récit","Le récit du feu","Le livre de la sagesse","Le récit de l'arche"],b:0,e:"« Nous te racontons le meilleur récit. »",s:['q:12:3']},
  {q:"Quel prophète a reçu la connaissance du langage des oiseaux ?",c:["Sulaymân","Yûnus","Nûh","Hûd"],b:0,e:"« On nous a appris le langage des oiseaux », dit Sulaymân.",s:['q:27:16']},
  {q:"Qui était le père de Sulaymân, lui aussi prophète et roi ?",c:["Dâwûd (David)","Ibrahim","Yaʿqûb","Mûsâ"],b:0,e:"« Et Sulaymân hérita de Dâwûd. »",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Mûsâ, celui à qui Allah a parlé",
 texte:["Mûsâ (Moïse) naquit en Égypte, à l'époque où Pharaon persécutait les Banû Isrâ'îl. Sur l'inspiration d'Allah, sa mère le déposa sur le fleuve, et la famille de Pharaon le recueillit.",
  "Allah lui parla directement et l'envoya vers Pharaon avec son frère Hârûn, et avec des miracles, comme son bâton qui devint un serpent.",
  "Allah fendit la mer pour sauver Mûsâ et son peuple, et Pharaon fut englouti. Mûsâ est le prophète le plus souvent cité dans le Coran."],
 retenir:"Mûsâ, sauvé des eaux, Kalîm Allâh, la mer fendue.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"Dans quel pays est né le prophète Mûsâ (Moïse) ?",c:["En Égypte","En Arabie","En Irak","Au Yémen"],b:0,e:"Il naquit en Égypte, sous le règne de Pharaon.",s:['q:28:7']},
  {q:"Que fit la mère de Mûsâ pour le protéger de Pharaon ?",c:["Elle le déposa sur le fleuve","Elle le cacha dans une grotte","Elle partit au désert","Elle le confia à un berger"],b:0,e:"Allah lui inspira de le jeter dans le fleuve, sans crainte.",s:['q:28:7']},
  {q:"Qui a recueilli Mûsâ bébé sur le fleuve ?",c:["La famille de Pharaon","Des pêcheurs","Ibrahim","Un roi du Yémen"],b:0,e:"Les gens de Pharaon le recueillirent.",s:['q:28:8']},
  {q:"Quel prophète est appelé « Kalîm Allâh », celui à qui Allah a parlé directement ?",c:["Mûsâ","Ibrahim","ʿÎsâ","Nûh"],b:0,e:"« Et Allah a parlé à Moïse de vive voix. »",s:['q:4:164']},
  {q:"Que devint le bâton de Mûsâ quand il le jeta à terre ?",c:["Un serpent","Un arbre","Une colombe","Une épée"],b:0,e:"« Il le jeta : et le voici un serpent qui rampait. »",s:['q:20:20']},
  {q:"Qu'arriva-t-il quand Mûsâ frappa la mer avec son bâton ?",c:["Elle se fendit en deux","Elle se transforma en sable","Elle s'assécha d'un coup","Rien"],b:0,e:"Chaque partie était comme une énorme montagne.",s:['q:26:63']},
  {q:"Qu'arriva-t-il à Pharaon et à son armée qui poursuivaient Mûsâ ?",c:["Ils furent engloutis par la mer","Ils se convertirent","Ils rentrèrent en Égypte","Ils traversèrent aussi"],b:0,e:"Allah sauva Mûsâ et ceux qui étaient avec lui, et engloutit les autres.",s:['q:26:66']},
  {q:"Comment s'appelait le frère de Mûsâ, qui l'aida dans sa mission ?",c:["Hârûn (Aaron)","Yûsuf","Isḥâq","Yaḥyâ"],b:0,e:"Mûsâ demanda à Allah de lui donner son frère Hârûn comme assistant.",s:['q:20:30']},
  {q:"Vers quel roi Allah envoya-t-Il Mûsâ ?",c:["Pharaon","Nemrod","Le roi de Saba","Goliath"],b:0,e:"« Rends-toi auprès de Pharaon car il a outrepassé toute limite. »",s:['q:20:24']},
  {q:"Quel prophète est le plus souvent cité par son nom dans le Coran ?",c:["Mûsâ","Muhammad ﷺ","Ibrahim","Nûh"],b:0,e:"Mûsâ est nommé plus de 130 fois dans le Coran.",s:['f:musa']}
 ]},
'pr-isa':{titre:"ʿÎsâ et Maryam",
 texte:["Maryam (Marie), mère de ʿÎsâ, est la seule femme nommée dans le Coran. Allah l'a choisie au-dessus des femmes des mondes, et une sourate porte son nom.",
  "ʿÎsâ (Jésus) est né sans père, par la volonté d'Allah, comme Adam fut créé sans père ni mère. Bébé, il parla dans son berceau.",
  "Pour les musulmans, ʿÎsâ est un grand prophète et messager d'Allah, le Messie, à qui fut révélé l'Injîl (Évangile)."],
 retenir:"Maryam, choisie entre les femmes. ʿÎsâ, né sans père, prophète et Messie.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Quelle est la seule femme nommée dans le Coran ?",c:["Maryam","Khadîja","Âsiya","Hawwâ'"],b:0,e:"Maryam est la seule femme citée par son nom ; la sourate 19 porte son nom.",s:['f:maryam']},
  {q:"Que dit le Coran de Maryam ?",c:["Allah l'a choisie au-dessus des femmes des mondes","Elle était reine d'Égypte","Elle était prophétesse de Médine","Le Coran n'en parle pas"],b:0,e:"Les anges lui annoncèrent qu'Allah l'avait élue et purifiée.",s:['q:3:42']},
  {q:"Comment est né le prophète ʿÎsâ (Jésus) ?",c:["Sans père, par la volonté d'Allah","Comme tout le monde","Dans le palais de Pharaon","À La Mecque"],b:0,e:"Allah dit « Sois », et il fut.",s:['q:3:59']},
  {q:"À la création de qui le Coran compare-t-il celle de ʿÎsâ ?",c:["À celle d'Adam","À celle des anges","À celle de Nûh","À celle d'Iblîs"],b:0,e:"Adam fut créé sans père ni mère ; ʿÎsâ sans père.",s:['q:3:59']},
  {q:"Quel miracle ʿÎsâ fit-il lorsqu'il était bébé ?",c:["Il parla dans son berceau","Il marcha sur l'eau","Il fit jaillir l'eau de Zamzam","Il traversa la mer"],b:0,e:"Il défendit sa mère en parlant depuis le berceau.",s:['q:19:30']},
  {q:"Quelles furent les premières paroles de ʿÎsâ bébé, selon le Coran ?",c:["« Je suis le serviteur d'Allah »","« Je suis roi »","« Je suis un ange »","« Je suis le fils de Zakariyyâ »"],b:0,e:"« Je suis vraiment le serviteur d'Allah. Il m'a donné le Livre et m'a désigné prophète. »",s:['q:19:30']},
  {q:"Quel titre le Coran donne-t-il à ʿÎsâ ?",c:["Al-Masîḥ, le Messie","Le Khalîl","Le sceau des prophètes","Kalîm Allâh"],b:0,e:"Les anges annoncent à Maryam : « son nom sera Al-Masîḥ, ʿÎsâ, fils de Marie ».",s:['q:3:45']},
  {q:"Quel livre Allah a-t-Il révélé au prophète ʿÎsâ ?",c:["L'Injîl (Évangile)","La Tawrât (Torah)","Le Zabûr (Psaumes)","Le Coran"],b:0,e:"« Nous lui avons donné l'Évangile, où il y a guide et lumière. »",s:['q:5:46']},
  {q:"Pour les musulmans, qui est ʿÎsâ ?",c:["Un prophète et messager d'Allah","Une divinité","Un ange","Un roi de Jérusalem"],b:0,e:"Il se présente lui-même comme serviteur d'Allah et prophète.",s:['q:19:30']},
  {q:"Qui fut envoyé à Maryam pour lui annoncer la naissance de ʿÎsâ ?",c:["L'Esprit d'Allah, l'ange Jibrîl","Zakariyyâ","Yaḥyâ","L'ange Mikâ'îl"],b:0,e:"Les savants expliquent que « Notre Esprit » désigne l'ange Jibrîl.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, le dernier prophète",
 texte:["Muhammad ﷺ est né à La Mecque vers 570, l'« année de l'Éléphant », dans la tribu de Quraysh. Orphelin de père avant sa naissance, il perdit sa mère Âmina à 6 ans et fut élevé par son grand-père, puis par son oncle Abû Ṭâlib.",
  "Connu pour son honnêteté, on l'appelait al-Amîn, « le digne de confiance ». Il reçut la première révélation à 40 ans.",
  "Il mourut à Médine en 632, à l'âge de 63 ans. Allah l'a envoyé comme miséricorde pour les mondes."],
 retenir:"Né à La Mecque vers 570, révélation à 40 ans, mort à Médine à 63 ans.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"Dans quelle ville est né le Prophète Muhammad ﷺ ?",c:["La Mecque","Médine","Jérusalem","Taïf"],b:0,e:"Il est né à La Mecque vers 570.",s:['f:sira']},
  {q:"Comment appelle-t-on l'année de naissance du Prophète ﷺ ?",c:["L'année de l'Éléphant","L'année de l'Hégire","L'année de la tristesse","L'année de la victoire"],b:0,e:"L'année où une armée venue avec des éléphants attaqua La Mecque (sourate 105).",s:['q:105:1']},
  {q:"Comment s'appelait la mère du Prophète ﷺ ?",c:["Âmina","Khadîja","Ḥalîma","Fâṭima"],b:0,e:"Âmina bint Wahb mourut quand il avait 6 ans.",s:['f:sira']},
  {q:"Quel oncle a élevé et protégé le Prophète ﷺ ?",c:["Abû Ṭâlib","Abû Lahab","Ḥamza","Al-ʿAbbâs"],b:0,e:"Après la mort de son grand-père, son oncle Abû Ṭâlib le prit en charge.",s:['f:sira']},
  {q:"Quel surnom les Mecquois donnaient-ils au Prophète ﷺ avant la révélation ?",c:["Al-Amîn, le digne de confiance","Al-Fârûq","Aṣ-Ṣiddîq","Sayf Allâh"],b:0,e:"Il était connu de tous pour son honnêteté.",s:['f:sira']},
  {q:"À quel âge le Prophète ﷺ est-il mort ?",c:["63 ans","40 ans","70 ans","53 ans"],b:0,e:"Ibn ʿAbbâs rapporte qu'il est mort à 63 ans.",s:['h:vie']},
  {q:"Dans quelle ville le Prophète ﷺ est-il mort ?",c:["Médine","La Mecque","Jérusalem","Damas"],b:0,e:"Il est mort à Médine en 632 et y est enterré.",s:['f:sira']},
  {q:"Selon le Coran, pourquoi Allah a-t-Il envoyé Muhammad ﷺ ?",c:["Comme miséricorde pour les mondes","Pour être roi","Pour punir les gens","Pour les seuls Arabes"],b:0,e:"« Nous ne t'avons envoyé qu'en miséricorde pour l'univers. »",s:['q:21:107']},
  {q:"Que dit le Coran du caractère du Prophète ﷺ ?",c:["Il est d'une moralité éminente","Il est sévère","Il est indifférent","Le Coran n'en parle pas"],b:0,e:"« Et tu es certes d'une moralité éminente. »",s:['q:68:4']},
  {q:"À quelle tribu appartenait le Prophète ﷺ ?",c:["Quraysh","Aws","Khazraj","Thaqîf"],b:0,e:"Quraysh, la grande tribu de La Mecque.",s:['f:sira']}
 ]},
'pr-livres':{titre:"Les livres révélés et la foi",
 texte:["Allah a révélé des livres à certains prophètes : la Tawrât (Torah) à Mûsâ, le Zabûr (Psaumes) à Dâwûd, l'Injîl (Évangile) à ʿÎsâ, et le Coran à Muhammad ﷺ.",
  "Le Coran nomme 25 prophètes, mais Allah en a envoyé bien d'autres. Le croyant croit en tous, sans distinction.",
  "La foi (îmân) repose sur six piliers : croire en Allah, en Ses anges, en Ses livres, en Ses messagers, au Jour dernier et au destin."],
 retenir:"Tawrât, Zabûr, Injîl, Coran. Six piliers de la foi.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Quel livre Allah a-t-Il révélé au prophète Mûsâ (Moïse) ?",c:["La Tawrât (Torah)","Le Zabûr (Psaumes)","L'Injîl (Évangile)","Le Coran"],b:0,e:"La Tawrât à Mûsâ, le Zabûr à Dâwûd, l'Injîl à ʿÎsâ, le Coran à Muhammad ﷺ.",s:['q:5:44']},
  {q:"Combien de prophètes sont cités par leur nom dans le Coran ?",c:["25","12","40","313"],b:0,e:"25 prophètes sont nommés ; 18 d'entre eux sont cités ensemble dans la sourate Al-Anʿâm.",s:['f:prophetes25']},
  {q:"Quel prophète le Coran appelle-t-il « le sceau des prophètes », c'est-à-dire le dernier ?",c:["Muhammad ﷺ","ʿÎsâ (Jésus)","Mûsâ (Moïse)","Ibrahim (Abraham)"],b:0,e:"Muhammad ﷺ est le dernier des prophètes.",s:['q:33:40']},
  {q:"Quel livre a été révélé au prophète Dâwûd (David) ?",c:["Le Zabûr (Psaumes)","La Tawrât","L'Injîl","Les feuillets d'Ibrahim"],b:0,e:"« Et Nous avons donné le Zabour à David. »",s:['q:4:163']},
  {q:"Croire aux livres révélés fait-il partie de la foi du musulman ?",c:["Oui, c'est un pilier de la foi","Non, seulement au Coran","Non, c'est facultatif","Seulement pendant le Ramadan"],b:0,e:"Les croyants croient en Allah, Ses anges, Ses livres et Ses messagers.",s:['q:2:285']},
  {q:"Combien de piliers compte la foi (îmân) ?",c:["6","5","4","10"],b:0,e:"Allah, les anges, les livres, les messagers, le Jour dernier et le destin.",s:['h:jibril']},
  {q:"Lequel de ces éléments n'est PAS un pilier de la foi (îmân) ?",c:["Le jeûne du Ramadan","La croyance aux anges","La croyance au Jour dernier","La croyance aux livres"],b:0,e:"Le jeûne est un pilier de l'islam (la pratique), pas de la foi (la croyance).",s:['h:jibril']},
  {q:"Quel livre Allah s'est-Il engagé à préserver ?",c:["Le Coran","La Tawrât","Le Zabûr","Tous les livres des rois"],b:0,e:"« C'est Nous qui en sommes gardien. »",s:['q:15:9']},
  {q:"Le Coran raconte-t-il l'histoire de tous les messagers envoyés par Allah ?",c:["Non, seulement de certains","Oui, de tous","Il n'en raconte aucun","Seulement des Arabes"],b:0,e:"« Il y a des messagers dont Nous t'avons raconté l'histoire, et d'autres dont Nous ne t'avons pas raconté l'histoire. »",s:['q:4:164']},
  {q:"Selon le Coran, les croyants font-ils une distinction entre les messagers dans leur foi ?",c:["Non, ils croient en tous","Oui, ils n'en croient qu'un","Oui, ils rejettent les anciens","Ils n'en croient aucun"],b:0,e:"« Nous ne faisons aucune distinction entre Ses messagers. »",s:['q:2:285']}
 ]},

/* ===================== HISTOIRE & COMPAGNONS ===================== */
'h-khadija':{titre:"Khadîja et les débuts de l'islam",
 texte:["Khadîja était une commerçante respectée de La Mecque. Elle épousa le Prophète ﷺ, qui avait alors 25 ans.",
  "Après la première révélation, c'est elle qui le réconforta et crut en lui la première. Elle l'emmena voir son cousin Waraqa ibn Nawfal.",
  "Parmi les premiers musulmans figurent Abû Bakr, ʿAlî, Zayd ibn Ḥâritha et Bilâl. Pendant 13 ans, à La Mecque, les musulmans furent persécutés ; Sumayya fut la première martyre."],
 retenir:"Khadîja, première à croire. 13 ans de prédication à La Mecque.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Qui fut la première épouse du Prophète ﷺ ?",c:["Khadîja","ʿÂ'icha","Ḥafṣa","Zaynab"],b:0,e:"Khadîja fut la première personne à croire en son message.",s:['h:hira']},
  {q:"Qui réconforta le Prophète ﷺ juste après la première révélation dans la grotte de Hira ?",c:["Khadîja","Abû Bakr","ʿAlî","Bilâl"],b:0,e:"Il rentra auprès de Khadîja, qui le rassura.",s:['h:hira']},
  {q:"Quelle activité exerçait Khadîja à La Mecque ?",c:["Le commerce","La médecine","La poésie","L'élevage de chameaux"],b:0,e:"C'était une riche commerçante respectée.",s:['f:debuts']},
  {q:"Quel âge avait le Prophète ﷺ lorsqu'il épousa Khadîja ?",c:["25 ans","40 ans","18 ans","30 ans"],b:0,e:"Il avait 25 ans.",s:['f:debuts']},
  {q:"Chez qui Khadîja emmena-t-elle le Prophète ﷺ après la première révélation ?",c:["Son cousin Waraqa ibn Nawfal","Abû Ṭâlib","Abû Bakr","Le roi d'Abyssinie"],b:0,e:"Waraqa connaissait les Écritures anciennes.",s:['h:hira']},
  {q:"Quel jeune garçon fut parmi les premiers à embrasser l'islam ?",c:["ʿAlî ibn Abî Ṭâlib","ʿUmar","Khâlid","Muʿâwiya"],b:0,e:"ʿAlî, cousin du Prophète ﷺ, était encore enfant.",s:['f:debuts']},
  {q:"Pendant combien d'années environ le Prophète ﷺ prêcha-t-il à La Mecque avant l'Hégire ?",c:["13 ans","3 ans","23 ans","40 ans"],b:0,e:"Ibn ʿAbbâs rapporte qu'il resta 13 ans à La Mecque après la révélation.",s:['h:vie']},
  {q:"Quel ami du Prophète ﷺ fut le premier homme adulte à embrasser l'islam ?",c:["Abû Bakr","ʿUmar","ʿUthmân","Ḥamza"],b:0,e:"Abû Bakr crut en lui sans hésiter.",s:['f:debuts']},
  {q:"Quel ancien esclave, persécuté pour sa foi, devint le premier muezzin de l'islam ?",c:["Bilâl ibn Rabâḥ","Zayd ibn Ḥâritha","Salmân","Anas"],b:0,e:"Sa voix portait loin : le Prophète ﷺ lui confia l'adhân.",s:['h:adhan']},
  {q:"Comment s'appelait la première martyre de l'islam ?",c:["Sumayya","Khadîja","Fâṭima","Asmâ'"],b:0,e:"Sumayya, mère de ʿAmmâr, fut tuée pour sa foi à La Mecque.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"L'Hégire",
 texte:["En 622, face aux persécutions, le Prophète ﷺ quitta La Mecque pour Médine, alors appelée Yathrib : c'est l'Hégire. Elle marque l'an 1 du calendrier musulman.",
  "Pendant le voyage, il se cacha dans la grotte de Thawr avec son ami Abû Bakr.",
  "À Médine, il fut accueilli par les Anṣâr (les « Auxiliaires »), qui partagèrent leurs biens avec les Muhâjirûn (les « Émigrés »). Il y construisit sa mosquée."],
 retenir:"622 : l'Hégire, an 1. Muhâjirûn et Anṣâr.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"Qu'est-ce que l'Hégire ?",c:["La migration du Prophète ﷺ de La Mecque à Médine","Le premier pèlerinage","Une bataille","La naissance du Prophète ﷺ"],b:0,e:"Elle marque l'an 1 du calendrier musulman.",s:['f:hegire']},
  {q:"Quel Compagnon accompagnait le Prophète ﷺ dans la grotte pendant l'Hégire ?",c:["Abû Bakr as-Siddîq","ʿUmar ibn al-Khaṭṭâb","ʿAlî ibn Abî Ṭâlib","Bilâl"],b:0,e:"Abû Bakr était « le second des deux » dans la grotte.",s:['q:9:40']},
  {q:"En quelle année a eu lieu l'Hégire ?",c:["622","570","632","610"],b:0,e:"L'Hégire a eu lieu en 622 de l'ère chrétienne.",s:['f:hegire']},
  {q:"Dans quelle grotte le Prophète ﷺ s'est-il caché pendant l'Hégire ?",c:["La grotte de Thawr","La grotte de Hira","La grotte d'Uhud","La grotte de Badr"],b:0,e:"Thawr est au sud de La Mecque ; Hira, lieu de la première révélation, au nord.",s:['f:hegire']},
  {q:"Quel était l'ancien nom de Médine ?",c:["Yathrib","Bakka","Taïf","Qubâ'"],b:0,e:"Le Coran cite ce nom : « Ô gens de Yathrib ».",s:['q:33:13']},
  {q:"Comment appelle-t-on les habitants de Médine qui accueillirent les musulmans ?",c:["Les Anṣâr","Les Muhâjirûn","Les Quraysh","Les Banû Isrâ'îl"],b:0,e:"Anṣâr signifie « les Auxiliaires ».",s:['q:9:100']},
  {q:"Comment appelle-t-on les musulmans qui émigrèrent de La Mecque à Médine ?",c:["Les Muhâjirûn","Les Anṣâr","Les Khawârij","Les Bédouins"],b:0,e:"Muhâjirûn signifie « les Émigrés ».",s:['q:9:100']},
  {q:"Que dit le Prophète ﷺ à Abû Bakr dans la grotte, selon le Coran ?",c:["« Ne t'afflige pas, Allah est avec nous »","« Fuyons vite »","« Rentrons à La Mecque »","« Combattons-les »"],b:0,e:"C'est le verset 40 de la sourate At-Tawba.",s:['q:9:40']},
  {q:"Sous quel calife le calendrier hégirien fut-il adopté ?",c:["ʿUmar","Abû Bakr","ʿUthmân","ʿAlî"],b:0,e:"ʿUmar fit de l'Hégire le point de départ du calendrier.",s:['f:hegire']},
  {q:"Qu'a construit le Prophète ﷺ en arrivant à Médine ?",c:["Sa mosquée","Un palais","Une forteresse","Un marché"],b:0,e:"La Mosquée du Prophète (al-Masjid an-Nabawî).",s:['f:hegire']}
 ]},
'h-badr':{titre:"La bataille de Badr",
 texte:["Le 17 Ramadan de l'an 2 de l'Hégire (624), les musulmans affrontèrent l'armée de Quraysh près des puits de Badr.",
  "Ils étaient environ 313, face à près de 1 000 combattants. Allah les soutint par des anges, et ils remportèrent la victoire.",
  "Le Coran appelle ce jour « le jour du Discernement » (yawm al-furqân), celui où la vérité fut distinguée de l'erreur."],
 retenir:"17 Ramadan an 2 : Badr, 313 contre 1 000, le jour du Discernement.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"Pendant quel mois a eu lieu la bataille de Badr ?",c:["Ramadan","Muharram","Dhû l-Hijja","Rajab"],b:0,e:"Le 17 Ramadan de l'an 2 de l'Hégire.",s:['f:badr']},
  {q:"En quelle année de l'Hégire a eu lieu la bataille de Badr ?",c:["L'an 2","L'an 8","L'an 10","L'an 1"],b:0,e:"En 624 de l'ère chrétienne.",s:['f:badr']},
  {q:"Combien de musulmans environ ont combattu à Badr ?",c:["Environ 313","Environ 3 000","Environ 10 000","Environ 50"],b:0,e:"Ils étaient environ 313.",s:['f:badr']},
  {q:"Combien de combattants environ comptait l'armée de Quraysh à Badr ?",c:["Près de 1 000","Près de 100","Près de 10 000","Près de 300"],b:0,e:"Les Mecquois étaient trois fois plus nombreux.",s:['f:badr']},
  {q:"Selon le Coran, comment Allah a-t-Il soutenu les musulmans à Badr ?",c:["Par des anges","Par une tempête de sable","Par des renforts de Perse","Par la pluie seulement"],b:0,e:"Allah répondit à leur appel en envoyant des anges.",s:['q:8:9']},
  {q:"Selon la sourate Al-Anfâl, combien d'anges Allah promit-Il d'envoyer en renfort à Badr ?",c:["Mille","Cent","Dix","Trois cents"],b:0,e:"« Je vais vous aider d'un millier d'anges déferlant les uns à la suite des autres. »",s:['q:8:9']},
  {q:"Comment le Coran appelle-t-il le jour de Badr ?",c:["Le jour du Discernement (yawm al-furqân)","Le jour de la Résurrection","Le jour de l'Aïd","Le jour de l'Hégire"],b:0,e:"Le jour où la vérité fut distinguée de l'erreur.",s:['q:8:41']},
  {q:"Contre quelle tribu les musulmans combattirent-ils à Badr ?",c:["Quraysh","Les Romains","Les Perses","Les Anṣâr"],b:0,e:"L'armée de Quraysh venait de La Mecque.",s:['f:badr']},
  {q:"À quel jour du Ramadan a eu lieu la bataille de Badr ?",c:["Le 17","Le 27","Le 1ᵉʳ","Le 10"],b:0,e:"Le 17 Ramadan de l'an 2.",s:['f:badr']},
  {q:"Selon le Coran, dans quelle situation étaient les musulmans à Badr ?",c:["Ils étaient faibles et humiliés","Ils étaient très nombreux","Ils étaient riches","Ils étaient à cheval"],b:0,e:"« Allah vous a donné la victoire, à Badr, alors que vous étiez humiliés. »",s:['q:3:123']}
 ]},
'h-fath':{titre:"La conquête de La Mecque",
 texte:["En l'an 8 de l'Hégire (630), pendant le mois de Ramadan, le Prophète ﷺ entra à La Mecque avec environ 10 000 musulmans, presque sans combat.",
  "Il pardonna à ses anciens ennemis et purifia la Kaaba de ses 360 idoles, en récitant : « La vérité est venue et l'erreur a disparu. »",
  "La sourate An-Naṣr annonce ce secours d'Allah et l'entrée des gens en foule dans l'islam."],
 retenir:"Ramadan an 8 : La Mecque ouverte, les idoles brisées, le pardon accordé.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"En quelle année de l'Hégire La Mecque fut-elle conquise ?",c:["L'an 8","L'an 2","L'an 1","L'an 11"],b:0,e:"En 630 de l'ère chrétienne.",s:['f:fath']},
  {q:"Pendant quel mois eut lieu la conquête de La Mecque ?",c:["Ramadan","Shawwâl","Dhû l-Hijja","Muharram"],b:0,e:"La conquête de La Mecque eut lieu en Ramadan.",s:['f:fath']},
  {q:"Combien de musulmans environ accompagnaient le Prophète ﷺ lors de la conquête de La Mecque ?",c:["Environ 10 000","Environ 313","Environ 1 000","Environ 100"],b:0,e:"Une armée d'environ 10 000 hommes.",s:['f:fath']},
  {q:"Combien d'idoles entouraient la Kaaba le jour de la conquête de La Mecque ?",c:["360","12","99","1 000"],b:0,e:"ʿAbdallah ibn Masʿûd rapporte qu'il y en avait 360.",s:['h:idoles']},
  {q:"Quel verset le Prophète ﷺ récita-t-il en abattant les idoles de la Kaaba ?",c:["« La vérité est venue et l'erreur a disparu »","« Au nom d'Allah »","« Dis : Il est Allah, Unique »","« Lis ! »"],b:0,e:"C'est le verset 81 de la sourate Al-Isrâ'.",s:['q:17:81','h:idoles']},
  {q:"Comment le Prophète ﷺ traita-t-il ses anciens ennemis mecquois après la conquête ?",c:["Il leur pardonna","Il les chassa","Il les emprisonna","Il les exila en Abyssinie"],b:0,e:"Il accorda un pardon général aux Mecquois.",s:['f:fath']},
  {q:"Quelle sourate annonce « le secours d'Allah et la victoire » ?",c:["An-Naṣr (110)","Al-Fatḥ (48)","Al-Fîl (105)","Al-Kawthar (108)"],b:0,e:"« Lorsque vient le secours d'Allah ainsi que la victoire. »",s:['q:110:1']},
  {q:"Selon la sourate An-Naṣr, comment les gens sont-ils entrés dans l'islam ?",c:["En foule","Un par un, en secret","Par la force","Aucun n'est entré"],b:0,e:"« Et que tu vois les gens entrer en foule dans la religion d'Allah. »",s:['q:110:2']},
  {q:"La conquête de La Mecque s'est-elle faite par une grande bataille ?",c:["Non, presque sans combat","Oui, la plus grande de l'histoire","Oui, pendant un an","Oui, au pied du mont Uhud"],b:0,e:"La ville fut ouverte pacifiquement, presque sans affrontement.",s:['f:fath']},
  {q:"Que demande la sourate An-Naṣr après la victoire ?",c:["Glorifier Allah et Lui demander pardon","Faire le hajj aussitôt","Jeûner trois jours","Reconstruire la Kaaba"],b:0,e:"« Célèbre la gloire de ton Seigneur et implore Son pardon. »",s:['q:110:3']}
 ]},
'h-califes':{titre:"Les quatre premiers califes",
 texte:["Après la mort du Prophète ﷺ en 632, quatre califes se succédèrent : Abû Bakr, ʿUmar, ʿUthmân et ʿAlî. On les appelle les « califes bien guidés ».",
  "Abû Bakr fit rassembler le Coran en un seul recueil par Zayd ibn Thâbit. Sous ʿUmar, l'islam s'étendit et le calendrier hégirien fut adopté.",
  "ʿUthmân fit copier le Coran en plusieurs exemplaires envoyés dans les provinces. ʿAlî, cousin et gendre du Prophète ﷺ, fut le quatrième calife."],
 retenir:"Abû Bakr, ʿUmar, ʿUthmân, ʿAlî : les quatre califes bien guidés.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Qui fut le premier calife après la mort du Prophète ﷺ ?",c:["Abû Bakr","ʿUmar","ʿAlî","ʿUthmân"],b:0,e:"Abû Bakr, puis ʿUmar, ʿUthmân et ʿAlî.",s:['f:califes']},
  {q:"Combien de « califes bien guidés » ont succédé au Prophète ﷺ ?",c:["4","3","5","12"],b:0,e:"On les appelle al-khulafâ' ar-râshidûn.",s:['f:califes']},
  {q:"Quel est l'ordre des quatre premiers califes ?",c:["Abû Bakr, ʿUmar, ʿUthmân, ʿAlî","ʿAlî, ʿUmar, Abû Bakr, ʿUthmân","ʿUmar, Abû Bakr, ʿAlî, ʿUthmân","ʿUthmân, ʿAlî, ʿUmar, Abû Bakr"],b:0,e:"De 632 à 661.",s:['f:califes']},
  {q:"Sous quel calife le Coran fut-il rassemblé pour la première fois en un seul recueil ?",c:["Abû Bakr","ʿUmar","ʿUthmân","ʿAlî"],b:0,e:"Après la bataille de Yamâma, où de nombreux récitateurs furent tués.",s:['h:compilation']},
  {q:"Quel Compagnon fut chargé de rassembler le Coran sous Abû Bakr ?",c:["Zayd ibn Thâbit","Bilâl","Khâlid ibn al-Walîd","Salmân"],b:0,e:"Zayd ibn Thâbit avait été scribe de la révélation.",s:['h:compilation']},
  {q:"Quel calife fit copier le Coran en plusieurs exemplaires envoyés dans les provinces ?",c:["ʿUthmân","Abû Bakr","ʿUmar","ʿAlî"],b:0,e:"Pour unifier la récitation dans tout le monde musulman.",s:['h:copies']},
  {q:"Quel lien de parenté unissait ʿAlî au Prophète ﷺ ?",c:["Son cousin et gendre","Son frère","Son oncle","Son grand-père"],b:0,e:"ʿAlî était l'époux de Fâṭima, fille du Prophète ﷺ.",s:['f:califes']},
  {q:"Quel calife était surnommé « al-Fârûq », celui qui distingue le vrai du faux ?",c:["ʿUmar","Abû Bakr","ʿUthmân","ʿAlî"],b:0,e:"ʿUmar ibn al-Khaṭṭâb.",s:['f:califes']},
  {q:"Quel calife était surnommé « aṣ-Ṣiddîq », le véridique ?",c:["Abû Bakr","ʿUmar","ʿUthmân","ʿAlî"],b:0,e:"Abû Bakr crut immédiatement à tout ce que rapportait le Prophète ﷺ.",s:['f:califes']},
  {q:"Quel calife épousa successivement deux filles du Prophète ﷺ ?",c:["ʿUthmân","ʿUmar","Abû Bakr","ʿAlî"],b:0,e:"D'où son surnom « Dhû n-Nûrayn », l'homme aux deux lumières.",s:['f:califes']}
 ]}
},

/* Repères (sources historiques ou pratiques, sans texte arabe) */
faits:{
 mois:{titre:"Repère",texte:"Les 12 mois hégiriens : Muharram, Safar, Rabîʿ al-awwal, Rabîʿ ath-thânî, Jumâdâ al-ûlâ, Jumâdâ al-âkhira, Rajab, Shaʿbân, Ramadan, Shawwâl, Dhû l-Qaʿda, Dhû l-Hijja."},
 jeune2:{titre:"Repère historique",texte:"Le jeûne du Ramadan a été prescrit à Médine, en l'an 2 de l'Hégire (624)."},
 conditions:{titre:"Repère",texte:"Les savants retiennent comme conditions de l'obligation du jeûne : être musulman, pubère, sain d'esprit et capable de jeûner."},
 aid:{titre:"Repère",texte:"L'islam compte deux fêtes : l'Aïd al-Fitr, le 1ᵉʳ Shawwâl, à la fin du Ramadan, et l'Aïd al-Adhâ, le 10 Dhû l-Hijja, pendant le hajj."},
 shahada:{titre:"Repère",texte:"Texte de la shahada : « Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh » — « J'atteste qu'il n'y a de divinité qu'Allah, et j'atteste que Muhammad est le Messager d'Allah »."},
 rakat:{titre:"Pratique transmise",texte:"Le nombre d'unités de chaque prière vient de la pratique du Prophète ﷺ, transmise par tous les musulmans : Fajr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshâ' 4, soit 17 rakʿât par jour."},
 zakat:{titre:"Repère",texte:"La zakat de l'argent est de 2,5 % (un quarantième) de l'épargne qui atteint le niṣâb et reste en possession pendant une année lunaire (le ḥawl). La sadaqa est une aumône volontaire. Pour les cas particuliers, il faut demander à un savant."},
 hajj:{titre:"Repère",texte:"Le hajj a lieu du 8 au 13 Dhû l-Hijja. Le pèlerin entre en iḥrâm (les hommes portent deux pièces de tissu blanc non cousues), fait le ṭawâf (sept tours de la Kaaba) et le saʿy (sept parcours entre Ṣafâ et Marwa). Le 9 est le jour de ʿArafa, le 10 l'Aïd al-Adhâ."},
 coran:{titre:"Repère",texte:"Le Coran compte 114 sourates et 6 236 versets selon le décompte le plus répandu. Il est divisé en 30 parties (juz'). Un verset se dit âya. Les sourates révélées avant l'Hégire sont dites mecquoises, celles d'après, médinoises. La plus longue est Al-Baqara (286 versets)."},
 tawba:{titre:"Repère",texte:"La sourate At-Tawba (9) est la seule des 114 sourates à ne pas commencer par « Bismi Llâhi r-Raḥmâni r-Raḥîm »."},
 ikhlas:{titre:"Repère",texte:"Al-Ikhlâs signifie « le monothéisme pur, la sincérité » : la sourate purifie la foi de toute association."},
 hawwa:{titre:"Repère",texte:"Le Coran mentionne l'épouse d'Adam sans la nommer. Son nom, Hawwâ' (Ève), vient de la Sunna et des savants."},
 musa:{titre:"Repère",texte:"Mûsâ est le prophète le plus souvent nommé dans le Coran : plus de 130 fois."},
 maryam:{titre:"Repère",texte:"Maryam est la seule femme citée par son nom dans le Coran. La sourate 19 porte son nom."},
 sira:{titre:"Repère historique",texte:"Le Prophète ﷺ est né à La Mecque vers 570, dans la tribu de Quraysh. Orphelin de père, il perdit sa mère Âmina à 6 ans, fut élevé par son grand-père ʿAbd al-Muṭṭalib puis par son oncle Abû Ṭâlib. On l'appelait al-Amîn. Il mourut à Médine en 632."},
 prophetes25:{titre:"Repère",texte:"25 prophètes sont nommés dans le Coran. 18 d'entre eux sont cités ensemble dans la sourate Al-Anʿâm (6), versets 83 à 86."},
 debuts:{titre:"Repère historique",texte:"Khadîja, riche commerçante, épousa le Prophète ﷺ quand il avait 25 ans. Parmi les tout premiers musulmans : Khadîja, Abû Bakr, ʿAlî (encore enfant), Zayd ibn Ḥâritha. Bilâl, esclave persécuté puis affranchi, devint le premier muezzin. Sumayya, mère de ʿAmmâr, fut la première martyre."},
 hegire:{titre:"Repère historique",texte:"L'Hégire eut lieu en 622. Le Prophète ﷺ et Abû Bakr se cachèrent dans la grotte de Thawr. Médine s'appelait Yathrib. Le Prophète ﷺ y construisit sa mosquée. Le calendrier hégirien fut adopté sous le califat de ʿUmar."},
 badr:{titre:"Repère historique",texte:"La bataille de Badr eut lieu le 17 Ramadan de l'an 2 (624). Environ 313 musulmans firent face à près de 1 000 combattants de Quraysh."},
 fath:{titre:"Repère historique",texte:"La Mecque fut ouverte en Ramadan de l'an 8 (630), presque sans combat, par environ 10 000 musulmans. Le Prophète ﷺ accorda un pardon général aux Mecquois."},
 califes:{titre:"Repère historique",texte:"Les quatre califes bien guidés : Abû Bakr aṣ-Ṣiddîq (632-634), ʿUmar al-Fârûq (634-644), ʿUthmân Dhû n-Nûrayn (644-656), qui épousa deux filles du Prophète ﷺ, Ruqayya puis Umm Kulthûm, et ʿAlî (656-661), cousin du Prophète ﷺ et époux de sa fille Fâṭima."}
},

/* Résumés affichés pour les hadiths longs (le texte complet reste accessible) */
resumes:{
 cinq:"Lors du Voyage nocturne (al-Isrâ' wa l-Miʿrâj), cinquante prières furent d'abord prescrites, puis allégées jusqu'à cinq prières par jour.",
 enfants:"ar-Rubayyiʿ bint Muʿawwidh raconte que les Compagnons faisaient jeûner leurs jeunes enfants le jour de ʿÂshûrâ', et leur donnaient des jouets en laine pour patienter jusqu'à la rupture.",
 hira:"ʿÂ'icha raconte que le Prophète ﷺ se retirait dans la grotte de Hira. L'ange vint et lui dit : « Lis ! ». Il rentra auprès de Khadîja, qui le réconforta, puis l'emmena voir son cousin Waraqa ibn Nawfal.",
 regles:"ʿÂ'icha explique qu'on leur ordonnait de rattraper le jeûne manqué pendant les règles, mais pas la prière.",
 tarawih:"Le Prophète ﷺ pria la nuit à la mosquée pendant le Ramadan ; des gens prièrent derrière lui, de plus en plus nombreux. Puis il cessa de sortir, craignant que cette prière ne leur soit rendue obligatoire.",
 adhan:"Le Compagnon ʿAbdallah ibn Zayd vit en rêve les paroles de l'adhân. Le Prophète ﷺ confirma ce rêve et demanda à Bilâl de lancer l'appel, car sa voix portait plus loin.",
 ikhlas:"Un homme récitait sans cesse la sourate Al-Ikhlâs et trouvait cela peu. Le Prophète ﷺ dit : « Elle équivaut à un tiers du Coran. »",
 kursi:"Le Prophète ﷺ demanda à Ubayy ibn Kaʿb quel est le plus grand verset du Livre d'Allah. Il répondit : Âyat al-Kursî. Le Prophète ﷺ le félicita pour sa science.",
 hajj_une:"Le Prophète ﷺ annonça que le hajj était prescrit. Un homme demanda : « Chaque année ? » Il répondit que s'il disait oui, cela deviendrait obligatoire chaque année : il est obligatoire une fois.",
 arafa:"Des gens interrogèrent le Prophète ﷺ à ʿArafa sur le pèlerinage. Il répondit : « Le hajj, c'est ʿArafa. »",
 jibril:"L'ange Jibrîl, sous forme humaine, interrogea le Prophète ﷺ sur l'islam, la foi et l'excellence. La foi (îmân) : croire en Allah, en Ses anges, en Ses livres, en Ses messagers, au Jour dernier et au destin, bon ou mauvais.",
 vie:"Ibn ʿAbbâs rapporte que le Prophète ﷺ reçut la révélation à 40 ans, resta 13 ans à La Mecque, émigra à Médine où il vécut 10 ans, et mourut à 63 ans.",
 idoles:"Le jour de la conquête, il y avait 360 idoles autour de la Kaaba. Le Prophète ﷺ les frappait avec un bâton en récitant : « La vérité est venue et l'erreur a disparu. »",
 compilation:"Après la bataille de Yamâma, où de nombreux récitateurs furent tués, Abû Bakr chargea Zayd ibn Thâbit de rassembler le Coran en un seul recueil.",
 copies:"ʿUthmân, inquiet des différences de récitation entre les provinces, fit copier le recueil du Coran en plusieurs exemplaires envoyés dans chaque région.",
 fitr_but:"Ibn ʿAbbâs rapporte que le Prophète ﷺ a prescrit la zakat al-fitr pour purifier le jeûneur des paroles futiles et inconvenantes, et pour nourrir les pauvres.",
 afw:"ʿÂ'icha demanda quoi dire si elle connaissait la Nuit du Destin. Il répondit : « Dis : Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî » — Ô Allah, Tu es Celui qui pardonne, Tu aimes le pardon, alors pardonne-moi."
}
};
